542: function rngFrom(seed) {
543:   let s = seed >>> 0;
544:   return () => {
545:     s += 0x6D2B79F5;
546:     let t = s;
547:     t = Math.imul(t ^ (t >>> 15), t | 1);
548:     t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
549:     return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
550:   };
551: }
