553: export function computeOutcome(march) {
554:   const target = TARGET_BY_ID[march.targetId];
555:   const atk = troopPower(march.units);
556:   const def = target.def;
557:   const ratio = atk / def;
558:   const win = ratio >= 1;
559:   const rng = rngFrom(hashString(march.id + target.id));
560:   const baseLoss = win
561:     ? clamp(0.52 / Math.max(ratio, 0.2), 0.06, 0.58)
562:     : clamp(0.6 + 0.25 * (1 - Math.min(ratio, 1)), 0.55, 0.9);
563:   const netLossRate = baseLoss * (1 - lossReduction());
564:   const recover = recoveryRate();
565:   const losses = {};
566:   const recovered = {};
567:   const survivors = {};
568:   let totalLost = 0;
569:   let totalRecovered = 0;
570:   for (const u of UNIT_DEFS) {
571:     const q = march.units[u.key] || 0;
572:     if (!q) continue;
573:     const raw = Math.min(q, Math.round(q * netLossRate * (0.82 + rng() * 0.36)));
574:     const rec = Math.min(raw, Math.floor(raw * recover * (0.7 + rng() * 0.6)));
575:     losses[u.key] = raw - rec;
576:     recovered[u.key] = rec;
577:     survivors[u.key] = q - raw + rec;
578:     totalLost += raw - rec;
579:     totalRecovered += rec;
580:   }
581:   const loot = {};
582:   if (win) {
583:     const base = targetLoot(target);
584:     const mult = 1 + lootBonus();
585:     for (const [k, v] of Object.entries(base)) loot[k] = Math.round(v * mult);
586:   }
587:   const xp = win ? Math.round(30 + target.level * 32 + def / 160) : Math.round(10 + def / 320);
588:   const heroXp = win ? Math.round(18 + target.level * 16) : 6;
589:   const sentCount = Object.values(march.units).reduce((a, b) => a + b, 0);
590:   return {
591:     id: 'a' + march.id,
592:     marchId: march.id,
593:     targetId: target.id,
594:     targetName: target.name,
595:     faction: target.faction,
596:     level: target.level,
597:     atk, def, ratio, win,
598:     losses, recovered, survivors,
599:     loot, xp, heroXp,
600:     lost: totalLost, recoveredTotal: totalRecovered,
601:     sentCount,
602:     sentUnits: { ...march.units },
603:     applied: false,
604:     time: Date.now()
605:   };
606: }
