703: export function startTicker() {
704:   if (tickTimer) return;
705:   lastTick = Date.now();
706:   tickTimer = setInterval(() => {
707:     const now = Date.now();
708:     const dt = Math.min(now - lastTick, 8 * 3600 * 1000);
709:     lastTick = now;
710:     applyProduction(dt);
711: 
712:     let structural = false;
713:     // buildings
714:     for (let i = state.buildQueue.length - 1; i >= 0; i--) {
715:       const q = state.buildQueue[i];
716:       if (now >= q.finishAt) {
717:         state.buildQueue.splice(i, 1);
718:         const b = state.buildings[q.buildingKey];
719:         if (b) {
720:           if (b.level === 0) state.stats.built += 1;
721:           b.level = q.toLevel;
722:         }
723:         structural = true;
724:         const def = BUILDING_BY_KEY[q.buildingKey];
725:         toast('OBRA CONCLUÍDA', `${def.name} agora está no nível ${q.toLevel}.`, 'good');
726:         emit('complete', { type: 'building', key: q.buildingKey, level: q.toLevel });
727:       }
728:     }
729:     // training
730:     for (let i = state.trainQueue.length - 1; i >= 0; i--) {
731:       const q = state.trainQueue[i];
732:       if (now >= q.finishAt) {
733:         state.trainQueue.splice(i, 1);
734:         state.troops[q.unitKey] = (state.troops[q.unitKey] || 0) + q.qty;
735:         state.stats.trained += q.qty;
736:         structural = true;
737:         const def = UNIT_BY_KEY[q.unitKey];
738:         toast('TREINAMENTO CONCLUÍDO', `${q.qty}× ${def.name} prontos para o combate.`, 'good');
739:         emit('complete', { type: 'training', key: q.unitKey, qty: q.qty });
740:       }
741:     }
742:     // research
743:     for (let i = state.researchQueue.length - 1; i >= 0; i--) {
744:       const q = state.researchQueue[i];
745:       if (now >= q.finishAt) {
746:         state.researchQueue.splice(i, 1);
747:         state.research[q.techKey] = q.toLevel;
748:         state.stats.researchCount += 1;
749:         structural = true;
