751:         emit('complete', { type: 'research', key: q.techKey, level: q.toLevel });
752:       }
753:     }
754:     // arrivals
755:     const before = state.arrivals.length + state.marches.length;
756:     processArrivals();
757:     if (before !== state.arrivals.length + state.marches.length) structural = true;
758: 
759:     emit('tick', { now, dt });
760:     if (structural) changed();
761:     else if (now - saveTimer > 5000) { saveTimer = now; save(); }
762:   }, 500);
763: }
