642: /* ============================ MODALS ============================ */
643: #modal-root{position:fixed;inset:0;z-index:80;pointer-events:none}
644: .modal-backdrop{position:absolute;inset:0;background:rgba(3,7,11,.74);backdrop-filter:blur(5px);pointer-events:auto;animation:fadeIn .18s ease}
645: .modal{
646:   position:absolute;left:50%;top:50%;transform:translate(-50%,-50%);width:min(560px,calc(100vw - 32px));max-height:calc(100vh - 40px);
647:   display:flex;flex-direction:column;pointer-events:auto;animation:modalIn .22s ease;
648:   background:linear-gradient(160deg,rgba(22,33,47,.98),rgba(9,15,23,.99));
649:   border:1px solid rgba(242,166,59,.26);
650:   clip-path:polygon(0 16px,16px 0,100% 0,100% calc(100% - 16px),calc(100% - 16px) 100%,0 100%);
651:   box-shadow:0 40px 100px rgba(0,0,0,.7),0 0 0 1px rgba(255,255,255,.04) inset;
652: }
653: .modal.wide{width:min(760px,calc(100vw - 32px))}
654: .modal.narrow{width:min(440px,calc(100vw - 32px))}
655: @keyframes modalIn{from{opacity:0;transform:translate(-50%,-47%) scale(.98)}to{opacity:1;transform:translate(-50%,-50%) scale(1)}}
656: .modal-head{display:flex;align-items:flex-start;gap:12px;padding:18px 20px 14px;border-bottom:1px solid var(--line);position:relative}
