  c.fillStyle = 'rgba(242,166,59,.7)';
  for (const [cx, cy] of [[gx + 0.32, gy + 0.32], [gx + w - 0.38, gy + 0.32], [gx + w - 0.38, gy + d - 0.38], [gx + 0.32, gy + d - 0.38]]) {
