/* ============================================================
   Mapa estratégico mundial — COMANDO GLOBAL
   ============================================================ */
import { TARGETS, TARGET_BY_ID, FACTION_COLORS, targetTravel, clamp } from './data.js';
import { state, targetState } from './state.js';

const BASE = { x: 53, y: 48 };

function smoothPath(c, pts, close = true) {
  const n = pts.length;
  if (n < 3) return;
  const mid = (a, b) => ({ x: (a.x + b.x) / 2, y: (a.y + b.y) / 2 });
  const first = mid(pts[n - 1], pts[0]);
  c.beginPath();
  c.moveTo(first.x, first.y);
  for (let i = 0; i < n; i++) {
    const cur = pts[i];
    const next = pts[(i + 1) % n];
    const m = mid(cur, next);
    c.quadraticCurveTo(cur.x, cur.y, m.x, m.y);
  }
  if (close) c.closePath();
}

function ring(c, x, y, r, color, lw = 1, dash = null) {
  c.save();
  c.strokeStyle = color;
  c.lineWidth = lw;
  if (dash) c.setLineDash(dash);
  c.beginPath();
  c.arc(x, y, r, 0, Math.PI * 2);
  c.stroke();
  c.restore();
}

const LAND = [
  [17, 12], [30, 7], [46, 9], [62, 8], [78, 14], [90, 24], [94, 38],
  [91, 53], [85, 67], [76, 81], [60, 91], [45, 90], [31, 84], [19, 72],
  [10, 57], [7, 41], [10, 25]
];

const ISLANDS = [
  [[6, 66], [11, 62], [14, 68], [12, 75], [7, 73]],
  [[88, 79], [93, 76], [96, 82], [92, 87], [88, 85]],
  [[63, 3], [67, 1], [70, 4], [66, 6]]
];

export class WorldRenderer {
  constructor(canvas, markerLayer, opts = {}) {
    this.canvas = canvas;
    this.layer = markerLayer;
    this.ctx = canvas.getContext('2d');
    this.onSelect = opts.onSelect || (() => {});
    this.dpr = 1;
    this.w = 1;
    this.h = 1;
    this.t = 0;
    this.running = false;
    this.static = null;
    this.markers = new Map();
    this.selected = null;
    this._raf = 0;
    this._last = 0;
    this._ro = new ResizeObserver(() => this.resize());
    this._ro.observe(canvas.parentElement || canvas);
    this.buildMarkers();
    this.resize();
  }

  buildMarkers() {
    this.layer.innerHTML = '';
    for (const t of TARGETS) {
      const b = document.createElement('button');
      b.className = 'wmarker enemy';
      b.dataset.target = t.id;
      b.style.left = `${t.x}%`;
      b.style.top = `${t.y}%`;
      b.setAttribute('aria-label', `${t.name}, nível ${t.level}, ${t.faction}`);
      b.innerHTML = `
        <span class="wm-diamond">
          <svg class="ico" aria-hidden="true"><use href="#${t.player ? 'i-crown' : 'i-flag'}"/></svg>
          <span class="wm-lvl">${t.player ? 'BASE' : t.level}</span>
        </span>
        <span class="wm-label">${t.name} · ${t.player ? 'SEU QG' : 'Nv ' + t.level}</span>
        ${t.player ? '<span class="wm-player-ring"></span><span class="wm-player-ring d2"></span>' : ''}`;
      b.addEventListener('click', (e) => {
        e.stopPropagation();
        this.onSelect(t.id);
      });
      this.layer.appendChild(b);
      this.markers.set(t.id, b);
    }
    this.refresh();
  }

  refresh() {
    for (const t of TARGETS) {
      const el = this.markers.get(t.id);
      if (!el) continue;
      const owner = state.targets[t.id]?.owner || 'enemy';
      el.classList.toggle('player', !!t.player);
      el.classList.toggle('conquered', !t.player && owner === 'player');
      el.classList.toggle('enemy', !t.player && owner !== 'player');
      el.classList.toggle('selected', this.selected === t.id);
      const lvl = el.querySelector('.wm-lvl');
      if (lvl) lvl.textContent = t.player ? 'BASE' : (owner === 'player' ? '✓' : t.level);
      const label = el.querySelector('.wm-label');
      if (label) label.textContent = `${t.name} · ${t.player ? 'SEU QG' : owner === 'player' ? 'DOMINADO' : 'Nv ' + t.level}`;
    }
  }

  setSelected(id) {
    this.selected = id;
    this.refresh();
  }

  resize() {
    const rect = this.canvas.getBoundingClientRect();
    this.w = Math.max(1, rect.width);
    this.h = Math.max(1, rect.height);
    this.dpr = Math.min(2, window.devicePixelRatio || 1);
    this.canvas.width = Math.round(this.w * this.dpr);
    this.canvas.height = Math.round(this.h * this.dpr);
    this.ctx.setTransform(this.dpr, 0, 0, this.dpr, 0, 0);
    this.buildStatic();
  }

  start() {
    if (this.running) return;
    this.running = true;
    this._last = performance.now();
    const loop = (now) => {
      if (!this.running) return;
      const dt = Math.min(60, now - this._last);
      this._last = now;
      this.t += dt;
      this.draw();
      this._raf = requestAnimationFrame(loop);
    };
    this._raf = requestAnimationFrame(loop);
  }

  stop() {
    this.running = false;
    cancelAnimationFrame(this._raf);
  }

  /* ---------------- static terrain ---------------- */
  buildStatic() {
    const w = this.w, h = this.h, dpr = this.dpr;
    const cv = document.createElement('canvas');
    cv.width = Math.round(w * dpr);
    cv.height = Math.round(h * dpr);
    const c = cv.getContext('2d');
    c.scale(dpr, dpr);
    const X = (p) => (p / 100) * w;
    const Y = (p) => (p / 100) * h;

    // ocean
    const bg = c.createRadialGradient(w * 0.52, h * 0.46, 20, w * 0.52, h * 0.46, Math.max(w, h) * 0.8);
    bg.addColorStop(0, '#0b1d27');
    bg.addColorStop(0.55, '#07141d');
    bg.addColorStop(1, '#03090e');
    c.fillStyle = bg;
    c.fillRect(0, 0, w, h);

    // sea texture
    c.save();
    c.globalAlpha = 0.22;
    c.strokeStyle = 'rgba(90,140,160,.18)';
    c.lineWidth = 1;
    for (let i = 0; i < 90; i++) {
      const x = (i * 37.7) % w;
      const y = (i * 61.3) % h;
      c.beginPath();
      c.moveTo(x, y);
      c.quadraticCurveTo(x + 12, y - 4, x + 26, y);
      c.stroke();
    }
    c.restore();

    // faction territories (soft glows)
    c.save();
    c.globalCompositeOperation = 'lighter';
    for (const t of TARGETS) {
      if (t.player) continue;
      const col = FACTION_COLORS[t.faction] || '#e3594c';
      const g = c.createRadialGradient(X(t.x), Y(t.y), 2, X(t.x), Y(t.y), Math.max(70, w * 0.09));
      g.addColorStop(0, this.hexA(col, 0.11));
      g.addColorStop(0.6, this.hexA(col, 0.045));
      g.addColorStop(1, this.hexA(col, 0));
      c.fillStyle = g;
      c.beginPath();
      c.arc(X(t.x), Y(t.y), Math.max(70, w * 0.09), 0, Math.PI * 2);
      c.fill();
    }
    c.restore();

    // main landmass
    const pts = LAND.map(([x, y]) => ({ x: X(x), y: Y(y) }));
    c.save();
    c.shadowColor = 'rgba(0,0,0,.75)';
    c.shadowBlur = 30;
    c.shadowOffsetY = 12;
    smoothPath(c, pts);
    const lg = c.createLinearGradient(0, 0, w, h);
    lg.addColorStop(0, '#25352f');
    lg.addColorStop(0.42, '#202f2b');
    lg.addColorStop(0.7, '#2a332b');
    lg.addColorStop(1, '#1a2726');
    c.fillStyle = lg;
    c.fill();
    c.restore();
    // coast glow layers
    smoothPath(c, pts);
    c.strokeStyle = 'rgba(90,175,180,.24)';
    c.lineWidth = 7;
    c.stroke();
    smoothPath(c, pts);
    c.strokeStyle = 'rgba(140,220,220,.38)';
    c.lineWidth = 1.2;
    c.stroke();

    // islands
    for (const isl of ISLANDS) {
      const ip = isl.map(([x, y]) => ({ x: X(x), y: Y(y) }));
      smoothPath(c, ip);
      c.fillStyle = '#1d2c29';
      c.fill();
      c.strokeStyle = 'rgba(120,190,190,.3)';
      c.lineWidth = 1;
      c.stroke();
    }

    // terrain bands / ridges
    c.save();
    smoothPath(c, pts);
    c.clip();
    // desert (south-west)
    const dg = c.createRadialGradient(X(22), Y(68), 10, X(22), Y(68), w * 0.18);
    dg.addColorStop(0, 'rgba(120,105,62,.4)');
    dg.addColorStop(1, 'rgba(120,105,62,0)');
    c.fillStyle = dg;
    c.fillRect(0, 0, w, h);
    // northern forests
    const fg = c.createRadialGradient(X(35), Y(22), 10, X(35), Y(22), w * 0.26);
    fg.addColorStop(0, 'rgba(54,84,56,.5)');
    fg.addColorStop(1, 'rgba(54,84,56,0)');
    c.fillStyle = fg;
    c.fillRect(0, 0, w, h);
    // red plains (east)
    const rg = c.createRadialGradient(X(78), Y(52), 10, X(78), Y(52), w * 0.24);
    rg.addColorStop(0, 'rgba(94,58,44,.38)');
    rg.addColorStop(1, 'rgba(94,58,44,0)');
    c.fillStyle = rg;
    c.fillRect(0, 0, w, h);

    // rivers
    c.strokeStyle = 'rgba(80,150,160,.22)';
    c.lineWidth = Math.max(1.5, w * 0.0022);
    c.beginPath();
    c.moveTo(X(41), Y(11));
    c.bezierCurveTo(X(47), Y(28), X(38), Y(42), X(46), Y(58));
    c.bezierCurveTo(X(52), Y(70), X(44), Y(80), X(51), Y(90));
    c.stroke();
    c.beginPath();
    c.moveTo(X(86), Y(28));
    c.bezierCurveTo(X(78), Y(40), X(82), Y(55), X(72), Y(66));
    c.stroke();

    // mountain ranges
    this.mountains(c, [
      [31, 27, 26], [36, 24, 20], [41, 26, 23], [26, 34, 17], [22, 42, 15],
      [70, 26, 15], [74, 31, 20], [78, 36, 17], [62, 68, 18], [68, 72, 15]
    ], X, Y);
    // forests
    c.fillStyle = 'rgba(49,78,52,.5)';
    for (let i = 0; i < 120; i++) {
      const x = 14 + (i * 17.3) % 70;
      const y = 12 + (i * 29.7) % 72;
      if (y > 34 && y < 58 && x > 55) continue;
      c.beginPath();
      c.arc(X(x), Y(y), 1.4 + (i % 3) * 0.6, 0, Math.PI * 2);
      c.fill();
    }
    // roads network
    const edges = [
      ['t1', 't2'], ['t2', 't14'], ['t14', 't13'], ['t13', 't12'], ['t12', 't11'],
      ['t11', 't10'], ['t10', 't9'], ['t9', 't8'], ['t8', 't7'], ['t7', 't6'],
      ['t6', 't5'], ['t5', 't4'], ['t4', 't3'], ['t3', 't15'], ['t15', 't16'],
      ['t16', 't17'], ['t17', 't14'], ['t16', 't18'], ['t15', 't18'], ['t5', 't16']
    ];
    c.save();
    c.lineWidth = Math.max(1.2, w * 0.0016);
    c.strokeStyle = 'rgba(205,185,140,.18)';
    for (const [a, b] of edges) {
      const ta = TARGET_BY_ID[a], tb = TARGET_BY_ID[b];
      if (!ta || !tb) continue;
      c.beginPath();
      c.moveTo(X(ta.x), Y(ta.y));
      c.quadraticCurveTo(X((ta.x + tb.x) / 2 + 2), Y((ta.y + tb.y) / 2 - 2), X(tb.x), Y(tb.y));
      c.stroke();
    }
    c.restore();
    c.restore();

    // latitude / longitude grid
    c.save();
    c.strokeStyle = 'rgba(130,180,200,.06)';
    c.lineWidth = 1;
    c.setLineDash([3, 7]);
    for (let i = 1; i < 10; i++) {
      c.beginPath(); c.moveTo((w * i) / 10, 0); c.lineTo((w * i) / 10, h); c.stroke();
      c.beginPath(); c.moveTo(0, (h * i) / 10); c.lineTo(w, (h * i) / 10); c.stroke();
    }
    c.restore();

    // labels
    const labels = [
      ['PLANÍCIE VERMELHA', 72, 44, 'rgba(227,120,100,.55)'],
      ['DESERTO DE VIDRO', 19, 70, 'rgba(232,193,90,.5)'],
      ['FLORESTA NEGRA', 30, 20, 'rgba(140,170,130,.42)'],
      ['MAR DE CINZAS', 51, 68, 'rgba(150,180,190,.32)'],
      ['PORTO NEGRO', 81, 58, 'rgba(190,200,210,.35)']
    ];
    c.save();
    c.textAlign = 'center';
    c.font = `600 ${Math.max(7, w * 0.0072)}px "Barlow Condensed",sans-serif`;
    for (const [txt, x, y, col] of labels) {
      c.fillStyle = col;
      c.save();
      c.translate(X(x), Y(y));
      c.letterSpacing = '2px';
      c.fillText(txt, 0, 0);
      c.restore();
    }
    c.restore();

    // map border ticks
    c.save();
    c.strokeStyle = 'rgba(180,200,210,.16)';
    c.lineWidth = 1;
    for (let i = 0; i < 25; i++) {
      const x = (w * i) / 24;
      c.beginPath(); c.moveTo(x, h - 8); c.lineTo(x, h - 2); c.stroke();
      const y = (h * i) / 24;
      c.beginPath(); c.moveTo(w - 8, y); c.lineTo(w - 2, y); c.stroke();
    }
    c.restore();

    this.static = cv;
  }

  mountains(c, list, X, Y) {
    for (const [x, y, s] of list) {
      const px = X(x), py = Y(y);
      const size = s * (this.w / 900) * 1.4;
      c.fillStyle = 'rgba(40,50,46,.8)';
      c.beginPath();
      c.moveTo(px - size, py + size * 0.4);
      c.lineTo(px, py - size * 0.65);
      c.lineTo(px + size, py + size * 0.4);
      c.closePath();
      c.fill();
      c.fillStyle = 'rgba(70,84,74,.7)';
      c.beginPath();
      c.moveTo(px - size * 0.15, py - size * 0.28);
      c.lineTo(px, py - size * 0.65);
      c.lineTo(px + size * 0.5, py + size * 0.1);
      c.closePath();
      c.fill();
      c.fillStyle = 'rgba(190,205,190,.22)';
      c.beginPath();
      c.moveTo(px - size * 0.18, py - size * 0.42);
      c.lineTo(px, py - size * 0.65);
      c.lineTo(px + size * 0.18, py - size * 0.42);
      c.closePath();
      c.fill();
    }
  }

  hexA(hex, a) {
    const n = parseInt(hex.slice(1), 16);
    return `rgba(${(n >> 16) & 255},${(n >> 8) & 255},${n & 255},${a})`;
  }

  /* ---------------- dynamic frame ---------------- */
  draw() {
    const c = this.ctx;
    c.clearRect(0, 0, this.w, this.h);
    if (this.static) c.drawImage(this.static, 0, 0, this.w, this.h);
    const X = (p) => (p / 100) * this.w;
    const Y = (p) => (p / 100) * this.h;
    const bx = X(BASE.x), by = Y(BASE.y);

    // radar sweep at player base
    c.save();
    c.globalCompositeOperation = 'lighter';
    const sweep = (this.t / 4200) % 1;
    const rad = Math.max(55, this.w * 0.075);
    c.fillStyle = 'rgba(69,211,198,.035)';
    c.beginPath();
    c.arc(bx, by, rad, 0, Math.PI * 2);
    c.fill();
    const sg = c.createRadialGradient(bx, by, 3, bx, by, rad);
    sg.addColorStop(0, 'rgba(69,211,198,.18)');
    sg.addColorStop(1, 'rgba(69,211,198,0)');
    c.fillStyle = sg;
    c.beginPath();
    c.moveTo(bx, by);
    c.arc(bx, by, rad, sweep * Math.PI * 2, sweep * Math.PI * 2 + 0.55);
    c.closePath();
    c.fill();
    c.restore();
    ring(c, bx, by, rad * 0.55, 'rgba(69,211,198,.18)', 1, [4, 7]);
    ring(c, bx, by, rad, 'rgba(69,211,198,.12)', 1, [2, 9]);

    // selection route
    if (this.selected && TARGET_BY_ID[this.selected] && !TARGET_BY_ID[this.selected].player) {
      const t = TARGET_BY_ID[this.selected];
      const tx = X(t.x), ty = Y(t.y);
      this.rotateDash(c, bx, by, tx, ty, this.t, 'rgba(242,166,59,.55)', Math.max(1, this.w * 0.002));
      const midx = (bx + tx) / 2, midy = (by + ty) / 2;
      const travel = targetTravel(t);
      this.tag(c, midx, midy - 8, `${travel}s · MARCHA`, 'rgba(242,166,59,.8)', 'rgba(8,13,18,.8)');
      const pulse = 4 + Math.sin(this.t / 250) * 2;
      ring(c, tx, ty, 16 + pulse, 'rgba(242,166,59,.55)', 1.5);
    }

    // active marches
    for (const m of state.marches) {
      const t = TARGET_BY_ID[m.targetId];
      if (!t) continue;
      const tx = X(t.x), ty = Y(t.y);
      const remain = clamp((m.arriveAt - Date.now()) / (m.travel * 1000), 0, 1);
      const progress = 1 - remain;
      this.rotateDash(c, bx, by, tx, ty, this.t, 'rgba(69,211,198,.35)', Math.max(1, this.w * 0.002));
      // moving convoy marker
      const px = bx + (tx - bx) * progress, py = by + (ty - by) * progress;
      c.save();
      c.fillStyle = '#45d3c6';
      c.shadowColor = '#45d3c6';
      c.shadowBlur = 10;
      c.beginPath();
      c.arc(px, py, 3.5, 0, Math.PI * 2);
      c.fill();
      c.restore();
      // arrowhead near target
      const ang = Math.atan2(ty - by, tx - bx);
      c.save();
      c.fillStyle = 'rgba(69,211,198,.7)';
      c.translate(tx, ty);
      c.rotate(ang);
      c.beginPath();
      c.moveTo(-2, 0); c.lineTo(-9, -4); c.lineTo(-9, 4);
      c.closePath(); c.fill();
      c.restore();
      this.tag(c, (bx + tx) / 2, (by + ty) / 2 + 8, `${Math.ceil((m.arriveAt - Date.now()) / 1000)}s`, 'rgba(130,235,225,.9)', 'rgba(6,16,20,.85)');
    }

    // moving clouds / smoke
    c.save();
    c.globalAlpha = 0.05;
    c.fillStyle = '#d9e8ee';
    for (let i = 0; i < 5; i++) {
      const x = ((this.t / 90 + i * 260) % (this.w + 300)) - 150;
      const y = this.h * (0.15 + i * 0.16);
      c.beginPath();
      c.ellipse(x, y, 90 + i * 20, 24 + i * 4, 0, 0, Math.PI * 2);
      c.fill();
    }
    c.restore();

    // vignette
    const vg = c.createRadialGradient(this.w / 2, this.h / 2, this.w * 0.2, this.w / 2, this.h / 2, this.w * 0.75);
    vg.addColorStop(0, 'rgba(0,0,0,0)');
    vg.addColorStop(1, 'rgba(0,0,0,.5)');
    c.fillStyle = vg;
    c.fillRect(0, 0, this.w, this.h);
  }

  rotateDash(c, x1, y1, x2, y2, t, color, lw) {
    c.save();
    c.strokeStyle = color;
    c.lineWidth = lw;
    c.setLineDash([6, 8]);
    c.lineDashOffset = -(t / 45) % 14;
    c.beginPath();
    c.moveTo(x1, y1);
    c.lineTo(x2, y2);
    c.stroke();
    c.restore();
  }

  tag(c, x, y, text, color, bg) {
    c.save();
    c.font = `700 ${Math.max(8, this.w * 0.0072)}px "Barlow Condensed",sans-serif`;
    const w = c.measureText(text).width + 10;
    c.fillStyle = bg;
    c.fillRect(x - w / 2, y - 7, w, 14);
    c.strokeStyle = color;
    c.globalAlpha = 0.5;
    c.lineWidth = 1;
    c.strokeRect(x - w / 2, y - 7, w, 14);
    c.globalAlpha = 1;
    c.fillStyle = color;
    c.textAlign = 'center';
    c.textBaseline = 'middle';
    c.fillText(text, x, y + 0.5);
    c.restore();
  }

  destroy() {
    this.stop();
    this._ro.disconnect();
  }
}

/* ============================================================
   Cena de batalha animada — COMANDO GLOBAL
   ============================================================ */
import { UNIT_BY_KEY, UNIT_DEFS, HERO_BY_KEY, FACTION_COLORS, fmt, clamp } from './data.js';
import { state } from './state.js';
import {
  battleStart, gunfire, explosion, victory, defeat,
  startBattleAmbience, stopBattleAmbience
} from './audio.js';

const DURATION = 7600;

function rnd(seed) {
  let s = seed >>> 0;
  return () => {
    s = (s * 1664525 + 1013904223) >>> 0;
    return s / 4294967296;
  };
}

export class BattleScene {
  constructor(root, opts = {}) {
    this.root = root;
    this.onFinish = opts.onFinish || (() => {});
    this.active = false;
    this.resultShown = false;
    this.done = false;
    this.outcome = null;
    this.units = [];
    this.tracers = [];
    this.explosions = [];
    this.sparks = [];
    this.shake = 0;
    this.t = 0;
    this._raf = 0;
    this._last = 0;
    this._nextTrace = 0;
    this._nextBoom = 0;
    this._nextGun = 0;
    this._resize = () => this.resize();
    this.root.addEventListener('click', (e) => {
      const btn = e.target.closest('[data-b-action]');
      if (!btn) return;
      const act = btn.dataset.bAction;
      if (act === 'skip') this.showResult();
      if (act === 'continue') this.finish();
    });
  }

  play(outcome) {
    this.outcome = outcome;
    this.resultShown = false;
    this.done = false;
    this.active = true;
    this.t = 0;
    this.units = [];
    this.tracers = [];
    this.explosions = [];
    this.sparks = [];
    this.shake = 0;
    this._nextTrace = 0;
    this._nextBoom = 900;
    this._nextGun = 200;
    this.root.hidden = false;
    const hero = HERO_BY_KEY[state.activeHero] || HERO_BY_KEY.valkyrie;
    const factionColor = FACTION_COLORS[outcome.faction] || '#e3594c';
    this.root.innerHTML = `
      <div class="battle" style="--enemy:${factionColor}">
        <canvas id="battle-canvas" aria-label="Campo de batalha"></canvas>
        <div class="battle-vignette"></div>
        <div class="battle-top">
          <div class="battle-side">
            <small>FORÇA DE ATAQUE · ${hero.name}</small>
            <b>${state.player.name}</b>
            <div class="bp"><svg class="ico"><use href="#i-sword"/></svg> ${fmt(outcome.atk)} PODER</div>
            <div class="battle-bar"><i id="b-bar-player"></i></div>
          </div>
          <div class="battle-center">
            <div class="bt-phase" id="b-phase">RECONHECIMENTO</div>
            <div class="bt-timer" id="b-timer">00:08</div>
            <div class="bt-sub">SETOR ${outcome.targetId.replace('t', '')} · ${outcome.targetName.toUpperCase()}</div>
          </div>
          <div class="battle-side right">
            <small>${outcome.faction}</small>
            <b>${outcome.targetName}</b>
            <div class="bp"><svg class="ico"><use href="#i-shield"/></svg> ${fmt(outcome.def)} DEFESA</div>
            <div class="battle-bar"><i id="b-bar-enemy"></i></div>
          </div>
        </div>
        <div class="battle-bottom">
          <div class="battle-log" id="b-log"><b>SISTEMA:</b> Unidades em posição. Aguardando ordem de fogo.</div>
          <div class="battle-skip">
            <button class="btn ghost small" data-b-action="skip"><svg class="ico"><use href="#i-arrow"/></svg> ACELERAR COMBATE</button>
          </div>
        </div>
        <div class="battle-result" id="b-result" hidden></div>
      </div>`;
    this.canvas = this.root.querySelector('#battle-canvas');
    this.ctx = this.canvas.getContext('2d');
    this.barPlayer = this.root.querySelector('#b-bar-player');
    this.barEnemy = this.root.querySelector('#b-bar-enemy');
    this.phaseEl = this.root.querySelector('#b-phase');
    this.timerEl = this.root.querySelector('#b-timer');
    this.logEl = this.root.querySelector('#b-log');
    this.resultEl = this.root.querySelector('#b-result');
    this.resize();
    window.addEventListener('resize', this._resize);
    this.buildUnits();
    battleStart();
    startBattleAmbience();
    this._last = performance.now();
    this._raf = requestAnimationFrame((n) => this.loop(n));
  }

  buildUnits() {
    const o = this.outcome;
    const r = rnd(9137 + o.level * 71);
    const friendly = [];
    for (const def of UNIT_DEFS) {
      const q = o.sentUnits?.[def.key] || 0;
      if (!q) continue;
      const n = clamp(Math.ceil(q / Math.max(1, Math.round((o.sentCount + 8) / 26))), 1, 8);
      for (let i = 0; i < n; i++) friendly.push(def.key === 'helicopter' ? 'heli' : def.key === 'tank' || def.key === 'artillery' ? 'tank' : 'inf');
    }
    const enemy = [];
    const eInf = clamp(8 + o.level * 3, 8, 26);
    for (let i = 0; i < eInf; i++) enemy.push('inf');
    for (let i = 0; i < clamp(o.level, 1, 8); i++) enemy.push('tank');
    if (o.level >= 3) enemy.push('heli');

    const make = (list, side) => list.map((type, i) => {
      const lane = (i + 0.5) / list.length;
      const y = 0.56 + ((lane * 0.82 + r() * 0.12) % 0.34);
      const depth = clamp((y - 0.56) / 0.34, 0, 1);
      return {
        side, type,
        x0: side === 'left' ? 0.12 + r() * 0.16 : 0.9 - r() * 0.15,
        x: 0,
        y,
        scale: 0.55 + depth * 1.05,
        delay: r() * 0.9,
        speed: 0.032 + r() * 0.035,
        bob: r() * Math.PI * 2,
        dieAt: side === 'right'
          ? (this.outcome.win ? 3.4 + r() * 3.2 : 99)
          : (this.outcome.win ? 5.8 + r() * 2.2 : 2.8 + r() * 3.4),
        recoil: 0
      };
    });
    this.units = [...make(friendly, 'left'), ...make(enemy, 'right')].sort((a, b) => a.y - b.y);
  }

  resize() {
    if (!this.canvas) return;
    const rect = this.canvas.getBoundingClientRect();
    this.w = Math.max(1, rect.width);
    this.h = Math.max(1, rect.height);
    this.dpr = Math.min(2, window.devicePixelRatio || 1);
    this.canvas.width = Math.round(this.w * this.dpr);
    this.canvas.height = Math.round(this.h * this.dpr);
    this.ctx.setTransform(this.dpr, 0, 0, this.dpr, 0, 0);
  }

  loop(now) {
    if (!this.active) return;
    const dt = Math.min(50, now - this._last);
    this._last = now;
    this.t += dt;
    if (!this.resultShown && this.t >= DURATION) this.showResult();
    this.update(dt);
    this.draw();
    this._raf = requestAnimationFrame((n) => this.loop(n));
  }

  update(dt) {
    if (this.resultShown) {
      this.units.forEach(u => { u.recoil *= 0.9; });
    }
    const prog = clamp(this.t / DURATION, 0, 1);
    for (const u of this.units) {
      const targetX = u.side === 'left' ? 0.43 : 0.57;
      const moveT = clamp((prog - u.delay * 0.16) / 0.55, 0, 1);
      u.x = u.x0 + (targetX - u.x0) * easeOut(moveT);
      u.recoil *= Math.pow(0.86, dt / 16);
    }
    if (!this.resultShown) {
      if (this.t > this._nextTrace && this.t < DURATION - 400) {
        this.spawnTracer();
        this._nextTrace = this.t + 45 + Math.random() * 130;
      }
      if (this.t > this._nextGun) {
        gunfire();
        this._nextGun = this.t + 700 + Math.random() * 900;
      }
      if (this.t > this._nextBoom && this.t < DURATION - 500) {
        this.spawnExplosion(0.36 + Math.random() * 0.28, 0.58 + Math.random() * 0.3, 0.6 + Math.random() * 0.9);
        if (Math.random() < 0.55) explosion();
        this.shake = Math.min(9, this.shake + 4);
        this._nextBoom = this.t + 320 + Math.random() * 700;
      }
      // HUD
      const e = this.outcome;
      const playerRatio = e.win ? 1 - 0.5 * easeIn(prog) : 1 - 0.92 * easeIn(prog);
      const enemyRatio = e.win ? 1 - 0.97 * easeIn(Math.max(0, (prog - 0.18) / 0.82)) : 1 - 0.45 * easeIn(prog);
      if (this.barPlayer) this.barPlayer.style.width = `${clamp(playerRatio * 100, 0, 100)}%`;
      if (this.barEnemy) this.barEnemy.style.width = `${clamp(enemyRatio * 100, 0, 100)}%`;
      if (this.timerEl) {
        const left = Math.max(0, DURATION - this.t);
        this.timerEl.textContent = `00:${String(Math.ceil(left / 1000)).padStart(2, '0')}`;
      }
      if (this.phaseEl) {
        const phase = this.t < 1400 ? 'RECONHECIMENTO' : this.t < 3200 ? 'BOMBARDEIO PREPARATÓRIO' : this.t < 5400 ? 'ASSALTO TERRESTRE' : 'COMBATE CORPO A CORPO';
        if (this.phaseEl.textContent !== phase) {
          this.phaseEl.textContent = phase;
          this.pushLog(phase);
        }
      }
    }
    // effects
    for (const p of this.tracers) p.life -= dt;
    this.tracers = this.tracers.filter(p => p.life > 0);
    for (const e of this.explosions) e.t += dt;
    this.explosions = this.explosions.filter(e => e.t < 900);
    for (const s of this.sparks) {
      s.x += s.vx * dt / 1000;
      s.y += s.vy * dt / 1000;
      s.vy += 260 * dt / 1000;
      s.life -= dt;
    }
    this.sparks = this.sparks.filter(s => s.life > 0);
    this.shake *= Math.pow(0.88, dt / 16);
  }

  pushLog(text) {
    if (!this.logEl) return;
    this.logEl.innerHTML = `<b>SISTEMA:</b> ${text}`;
  }

  spawnTracer() {
    const shooters = this.units.filter(u => u.type !== 'heli' && Math.sin(this.t / 2000 + u.bob) > -0.9);
    if (!shooters.length) return;
    const shooter = shooters[Math.floor(Math.random() * shooters.length)];
    if (this.t / 1000 > shooter.dieAt) return;
    const side = shooter.side;
    const targets = this.units.filter(u => u.side !== side);
    if (!targets.length) return;
    const target = targets[Math.floor(Math.random() * targets.length)];
    const from = this.unitScreen(shooter, true);
    const to = this.unitScreen(target, false);
    this.tracers.push({ x1: from.x, y1: from.y, x2: to.x + (Math.random() - 0.5) * 18, y2: to.y + (Math.random() - .5) * 12, life: 80 + Math.random() * 70, max: 150 });
    shooter.recoil = 1;
    for (let i = 0; i < 3; i++) {
      this.sparks.push({ x: from.x, y: from.y, vx: (Math.random() - .5) * 90 + (side === 'left' ? 60 : -60), vy: (Math.random() - .5) * 70, life: 160 + Math.random() * 120, color: '#ffd48a' });
    }
  }

  spawnExplosion(x, y, size) {
    this.explosions.push({ x, y, size, t: 0, hue: Math.random() < 0.5 ? 28 : 42 });
    for (let i = 0; i < 16; i++) {
      const a = Math.random() * Math.PI * 2;
      const sp = 40 + Math.random() * 230;
      this.sparks.push({ x: x * this.w, y: y * this.h, vx: Math.cos(a) * sp, vy: Math.sin(a) * sp - 60, life: 350 + Math.random() * 450, color: Math.random() < .6 ? '#ffb057' : '#ffe2a4' });
    }
  }

  unitScreen(u, muzzle) {
    const x = u.x * this.w;
    const y = u.y * this.h;
    const scale = u.scale * clamp(this.h / 720, 0.7, 1.4);
    const off = u.side === 'left' ? 1 : -1;
    if (u.type === 'heli') return { x: x + (muzzle ? off * 16 : 0) * scale, y: y - 30 * scale };
    if (u.type === 'tank') return { x: x + (muzzle ? off * 22 * scale : 0), y: y - 10 * scale };
    return { x: x + (muzzle ? off * 9 * scale : 0), y: y - 9 * scale };
  }

  draw() {
    const c = this.ctx;
    const w = this.w, h = this.h;
    c.clearRect(0, 0, w, h);
    c.save();
    if (this.shake > 0.2) c.translate((Math.random() - .5) * this.shake, (Math.random() - .5) * this.shake);
    this.drawSky(c, w, h);
    this.drawGround(c, w, h);
    // explosions behind units for smoke
    for (const e of this.explosions) this.drawExplosion(c, e);
    for (const u of this.units) this.drawUnit(c, u);
    // tracers
    for (const p of this.tracers) {
      const a = clamp(p.life / p.max, 0, 1);
      c.save();
      c.globalCompositeOperation = 'lighter';
      c.strokeStyle = `rgba(255,220,150,${a * 0.9})`;
      c.lineWidth = 1.4;
      c.shadowColor = '#ffcf7a';
      c.shadowBlur = 5;
      c.beginPath();
      c.moveTo(p.x1, p.y1);
      c.lineTo(p.x2, p.y2);
      c.stroke();
      c.restore();
    }
    // sparks
    for (const s of this.sparks) {
      c.fillStyle = s.color;
      c.globalAlpha = clamp(s.life / 500, 0, 1);
      c.fillRect(s.x, s.y, 2, 2);
    }
    c.globalAlpha = 1;
    // foreground dust
    const dust = c.createLinearGradient(0, h * 0.62, 0, h);
    dust.addColorStop(0, 'rgba(40,32,22,0)');
    dust.addColorStop(1, 'rgba(12,10,8,.55)');
    c.fillStyle = dust;
    c.fillRect(0, h * 0.62, w, h * 0.38);
    c.restore();
  }

  drawSky(c, w, h) {
    const horizon = h * 0.52;
    const sky = c.createLinearGradient(0, 0, 0, horizon);
    sky.addColorStop(0, '#0b1119');
    sky.addColorStop(0.45, '#242b31');
    sky.addColorStop(0.72, '#6b4b39');
    sky.addColorStop(0.9, '#b56c3b');
    sky.addColorStop(1, '#d18a50');
    c.fillStyle = sky;
    c.fillRect(0, 0, w, horizon + 2);
    // stars
    const rs = rnd(77);
    c.fillStyle = 'rgba(220,235,245,.55)';
    for (let i = 0; i < 70; i++) {
      const x = rs() * w, y = rs() * h * 0.33;
      const a = 0.15 + rs() * 0.5;
      c.globalAlpha = a;
      c.fillRect(x, y, 1.2, 1.2);
    }
    c.globalAlpha = 1;
    // sun glow
    const sunX = w * 0.7, sunY = horizon - h * 0.035;
    const sg = c.createRadialGradient(sunX, sunY, 2, sunX, sunY, w * 0.32);
    sg.addColorStop(0, 'rgba(255,180,100,.42)');
    sg.addColorStop(0.35, 'rgba(240,130,60,.16)');
    sg.addColorStop(1, 'rgba(240,130,60,0)');
    c.fillStyle = sg;
    c.fillRect(0, 0, w, horizon);
    c.fillStyle = 'rgba(255,196,130,.5)';
    c.beginPath();
    c.arc(sunX, sunY, 22, 0, Math.PI * 2);
    c.fill();
    // clouds
    c.save();
    c.globalAlpha = 0.22;
    c.fillStyle = '#20262c';
    for (let i = 0; i < 5; i++) {
      const cx = ((this.t / 160 + i * w * 0.29) % (w + 300)) - 120;
      const cy = h * (0.08 + i * 0.06);
      c.beginPath();
      c.ellipse(cx, cy, 90 + i * 26, 9 + i * 2.5, 0.03, 0, Math.PI * 2);
      c.fill();
    }
    c.restore();
    // distant mountains
    const m1 = rnd(421);
    c.fillStyle = 'rgba(22,26,28,.9)';
    c.beginPath();
    c.moveTo(0, horizon);
    let x = 0;
    while (x < w) {
      const peak = h * (0.08 + m1() * 0.11);
      c.lineTo(x + w * 0.045, horizon - peak);
      x += w * 0.045;
      c.lineTo(x, horizon + 2);
    }
    c.closePath();
    c.fill();
    const m2 = rnd(817);
    c.fillStyle = 'rgba(12,16,18,.95)';
    c.beginPath();
    c.moveTo(0, horizon);
    x = 0;
    while (x < w) {
      const peak = h * (0.025 + m2() * 0.075);
      c.lineTo(x + w * 0.06, horizon - peak);
      x += w * 0.06;
      c.lineTo(x, horizon + 3);
    }
    c.closePath();
    c.fill();
    // ruined skyline
    const rs2 = rnd(9001);
    c.fillStyle = '#101413';
    for (let i = 0; i < 22; i++) {
      const bx = rs2() * w;
      const bw = 8 + rs2() * 30;
      const bh = 12 + rs2() * h * 0.11;
      c.fillRect(bx, horizon - bh, bw, bh);
      if (rs2() > 0.6) {
        c.fillRect(bx + bw * 0.4, horizon - bh - 6, 2, 7);
        c.fillStyle = 'rgba(227,89,76,.55)';
        c.fillRect(bx + bw * 0.4, horizon - bh - 7, 2, 2);
        c.fillStyle = '#101413';
      }
    }
    // searchlights
    const beam = (px, ang, alpha) => {
      c.save();
      c.globalCompositeOperation = 'lighter';
      const g = c.createLinearGradient(px, horizon, px + Math.cos(ang) * h * 0.5, horizon + Math.sin(ang) * h * 0.5);
      g.addColorStop(0, `rgba(180,210,230,${alpha})`);
      g.addColorStop(1, 'rgba(180,210,230,0)');
      c.fillStyle = g;
      c.beginPath();
      c.moveTo(px, horizon);
      c.lineTo(px + Math.cos(ang - 0.05) * h * 0.65, horizon + Math.sin(ang - 0.05) * h * 0.65);
      c.lineTo(px + Math.cos(ang + 0.05) * h * 0.65, horizon + Math.sin(ang + 0.05) * h * 0.65);
      c.closePath();
      c.fill();
      c.restore();
    };
    const s1 = -1.65 + Math.sin(this.t / 2600) * 0.35;
    const s2 = -1.5 + Math.sin(this.t / 3100 + 1.3) * 0.4;
    beam(w * 0.2, s1, 0.05);
    beam(w * 0.82, s2, 0.045);
  }

  drawGround(c, w, h) {
    const horizon = h * 0.52;
    const g = c.createLinearGradient(0, horizon, 0, h);
    g.addColorStop(0, '#6b5637');
    g.addColorStop(0.18, '#4b402b');
    g.addColorStop(0.55, '#2b261c');
    g.addColorStop(1, '#12110d');
    c.fillStyle = g;
    c.fillRect(0, horizon, w, h - horizon);
    // distant haze
    const haze = c.createLinearGradient(0, horizon, 0, horizon + h * 0.12);
    haze.addColorStop(0, 'rgba(210,150,90,.25)');
    haze.addColorStop(1, 'rgba(210,150,90,0)');
    c.fillStyle = haze;
    c.fillRect(0, horizon, w, h * 0.12);
    // perspective grid
    c.save();
    c.strokeStyle = 'rgba(200,190,160,.055)';
    c.lineWidth = 1;
    const vx = w * 0.5;
    for (let i = -8; i <= 8; i++) {
      c.beginPath();
      c.moveTo(vx + i * w * 0.035, horizon);
      c.lineTo(vx + i * w * 0.34, h);
      c.stroke();
    }
    for (let i = 1; i <= 7; i++) {
      const y = horizon + Math.pow(i / 7, 1.9) * (h - horizon);
      c.beginPath();
      c.moveTo(0, y);
      c.lineTo(w, y);
      c.stroke();
    }
    c.restore();
    // craters and debris
    const r = rnd(551);
    for (let i = 0; i < 26; i++) {
      const x = r() * w;
      const y = horizon + r() * (h - horizon);
      const dep = (y - horizon) / (h - horizon);
      const rx = (6 + r() * 26) * (0.3 + dep);
      c.fillStyle = 'rgba(10,9,7,.4)';
      c.beginPath();
      c.ellipse(x, y, rx, rx * 0.32, 0, 0, Math.PI * 2);
      c.fill();
      c.strokeStyle = 'rgba(190,170,130,.06)';
      c.stroke();
    }
    for (let i = 0; i < 40; i++) {
      const x = r() * w, y = horizon + r() * (h - horizon);
      c.fillStyle = 'rgba(190,180,150,.1)';
      c.fillRect(x, y, 2 + r() * 3, 1.5);
    }
    // smoke columns fixed
    const rs = rnd(331);
    c.save();
    c.globalAlpha = 0.16;
    for (let i = 0; i < 4; i++) {
      const sx = rs() * w;
      const sy = horizon - 4;
      for (let k = 0; k < 3; k++) {
        c.fillStyle = '#0c0d0b';
        c.beginPath();
        c.ellipse(sx + Math.sin(this.t / 1400 + i + k) * 10, sy - k * 26, 20 + k * 12, 14 + k * 8, 0, 0, Math.PI * 2);
        c.fill();
      }
    }
    c.restore();
  }

  drawUnit(c, u) {
    const x = u.x * this.w;
    const y = u.y * this.h;
    const s = u.scale * clamp(this.h / 720, 0.75, 1.5);
    const dead = this.t / 1000 > u.dieAt;
    const friendly = u.side === 'left';
    const body = friendly ? '#3a4a42' : '#4a3530';
    const dark = friendly ? '#232e29' : '#2d201d';
    const rim = friendly ? 'rgba(69,211,198,.4)' : 'rgba(227,89,76,.4)';
    c.save();
    c.translate(x, y);
    // shadow
    c.fillStyle = 'rgba(0,0,0,.38)';
    c.beginPath();
    c.ellipse(0, 2 * s, (u.type === 'tank' ? 18 : 8) * s, 3.2 * s, 0, 0, Math.PI * 2);
    c.fill();
    if (dead) {
      c.globalAlpha = 0.45;
      c.fillStyle = dark;
      c.beginPath();
      c.ellipse(0, 0, (u.type === 'tank' ? 14 : 7) * s, 2.6 * s, 0, 0, Math.PI * 2);
      c.fill();
      c.restore();
      return;
    }
    if (u.type === 'heli') {
      const hover = Math.sin(this.t / 240 + u.bob) * 4 * s;
      c.translate(0, -34 * s + hover);
      c.fillStyle = dark;
      c.beginPath();
      c.ellipse(0, 0, 11 * s, 4.2 * s, 0, 0, Math.PI * 2);
      c.fill();
      c.fillRect(-11 * s, -2 * s, 22 * s, 4 * s);
      c.fillRect(friendly ? 6 * s : -20 * s, -1.4 * s, 14 * s, 2.8 * s);
      c.fillStyle = rim;
      c.fillRect(-5 * s, -3.6 * s, 8 * s, 1.2 * s);
      // rotor
      c.strokeStyle = 'rgba(220,235,240,.4)';
      c.lineWidth = 1.2;
      const rw = (24 + Math.sin(this.t / 40) * 8) * s;
      c.beginPath(); c.moveTo(-rw, -5 * s); c.lineTo(rw, -5 * s); c.stroke();
      c.beginPath(); c.moveTo(-5 * s, -2 * s); c.lineTo(5 * s, -8 * s); c.stroke();
      c.strokeStyle = 'rgba(200,220,230,.5)';
      c.beginPath(); c.moveTo(-6 * s, 1 * s); c.lineTo(6 * s, 1 * s); c.stroke();
      c.restore();
      return;
    }
    if (u.type === 'tank') {
      const bob = Math.sin(this.t / 220 + u.bob) * 0.7 * s;
      c.translate(0, bob);
      // tracks
      c.fillStyle = '#191b19';
      c.fillRect(-16 * s, -5 * s, 32 * s, 6 * s);
      c.fillStyle = '#2c2d28';
      for (let i = -2; i <= 2; i++) c.fillRect(i * 6 * s - 1.5 * s, -4.5 * s, 3 * s, 5 * s);
      // hull
      c.fillStyle = body;
      c.beginPath();
      c.moveTo(-16 * s, -6 * s);
      c.lineTo(-10 * s, -13 * s);
      c.lineTo(11 * s, -13 * s);
      c.lineTo(16 * s, -6 * s);
      c.closePath();
      c.fill();
      c.strokeStyle = rim;
      c.lineWidth = 1;
      c.stroke();
      // turret
      c.fillStyle = dark;
      c.fillRect(-6 * s, -16 * s, 12 * s, 4 * s);
      c.strokeStyle = '#6d7b70';
      c.lineWidth = 2 * s;
      c.beginPath();
      c.moveTo(friendly ? 5 * s : -5 * s, -14 * s);
      c.lineTo(friendly ? 22 * s : -22 * s, -15 * s);
      c.stroke();
      if (u.recoil > 0.2) {
        c.fillStyle = 'rgba(255,214,140,.85)';
        c.beginPath();
        c.arc(friendly ? 23 * s : -23 * s, -15 * s, 3 * s * u.recoil, 0, Math.PI * 2);
        c.fill();
      }
      c.restore();
      return;
    }
    // infantry
    const bob = Math.sin(this.t / 160 + u.bob) * 0.8 * s;
    c.translate(0, bob);
    c.fillStyle = dark;
    c.fillRect(-2 * s, -4 * s, 1.6 * s, 4 * s);
    c.fillRect(0.6 * s, -4 * s, 1.6 * s, 4 * s);
    c.fillStyle = body;
    c.beginPath();
    c.moveTo(-4 * s, -13 * s);
    c.lineTo(4 * s, -13 * s);
    c.lineTo(3 * s, -4 * s);
    c.lineTo(-3 * s, -4 * s);
    c.closePath();
    c.fill();
    c.fillStyle = '#26332d';
    c.beginPath();
    c.arc(0, -15 * s, 2.8 * s, 0, Math.PI * 2);
    c.fill();
    c.strokeStyle = rim;
    c.lineWidth = 0.8;
    c.stroke();
    // rifle
    c.strokeStyle = '#141a17';
    c.lineWidth = 1.6 * s;
    c.beginPath();
    c.moveTo(friendly ? 3 * s : -3 * s, -10 * s);
    c.lineTo(friendly ? 12 * s : -12 * s, -11 * s);
    c.stroke();
    if (u.recoil > 0.25) {
      c.fillStyle = 'rgba(255,220,150,.9)';
      c.beginPath();
      c.arc(friendly ? 13 * s : -13 * s, -11 * s, 2.2 * s * u.recoil, 0, Math.PI * 2);
      c.fill();
    }
    c.restore();
  }

  drawExplosion(c, e) {
    const p = e.t / 900;
    const x = e.x * this.w, y = e.y * this.h;
    const r = e.size * (30 + p * 95) * clamp(this.h / 720, 0.7, 1.4);
    c.save();
    c.globalCompositeOperation = 'lighter';
    const g = c.createRadialGradient(x, y, 1, x, y, r);
    g.addColorStop(0, `rgba(255,240,200,${(1 - p) * 0.9})`);
    g.addColorStop(0.25, `rgba(255,170,70,${(1 - p) * 0.7})`);
    g.addColorStop(0.6, `rgba(210,80,30,${(1 - p) * 0.3})`);
    g.addColorStop(1, 'rgba(120,40,10,0)');
    c.fillStyle = g;
    c.beginPath();
    c.arc(x, y, r, 0, Math.PI * 2);
    c.fill();
    c.strokeStyle = `rgba(255,220,160,${(1 - p) * 0.35})`;
    c.lineWidth = 1.5;
    c.beginPath();
    c.arc(x, y, r * (0.6 + p * 0.6), 0, Math.PI * 2);
    c.stroke();
    c.restore();
    // smoke
    c.save();
    for (let i = 0; i < 4; i++) {
      const a = (1 - p) * 0.22;
      c.fillStyle = `rgba(35,32,28,${a})`;
      c.beginPath();
      c.ellipse(x + Math.sin(i * 2 + p * 3) * r * 0.4, y - p * r * (0.2 + i * 0.12), r * (0.35 + i * 0.1), r * (0.25 + i * 0.08), 0, 0, Math.PI * 2);
      c.fill();
    }
    c.restore();
  }

  showResult() {
    if (this.resultShown || !this.active) return;
    this.resultShown = true;
    stopBattleAmbience();
    const o = this.outcome;
    if (o.win) victory(); else defeat();
    this.barPlayer.style.width = o.win ? '52%' : '2%';
    this.barEnemy.style.width = o.win ? '1%' : '58%';
    if (this.phaseEl) this.phaseEl.textContent = o.win ? 'SETOR CONQUISTADO' : 'FORÇA DERROTADA';
    if (this.timerEl) this.timerEl.textContent = '00:00';
    this.resultEl.hidden = false;
    this.resultEl.className = `battle-result ${o.win ? 'win' : 'loss'}`;
    const loot = Object.entries(o.loot || {}).filter(([, v]) => v > 0).map(([k, v]) =>
      `<span class="loot-item" style="--rc:${k === 'oil' ? '#f0a33a' : k === 'steel' ? '#a9bfd2' : k === 'food' ? '#8fc45b' : '#e8c15a'}"><svg class="ico"><use href="#i-${k === 'oil' ? 'oil' : k === 'steel' ? 'steel' : k === 'food' ? 'food' : 'credit'}"/></svg>+${fmt(v)}</span>`
    ).join('');
    this.resultEl.innerHTML = `
      <div class="br-kicker">${o.win ? 'OPERAÇÃO CONCLUÍDA' : 'OPERAÇÃO FRACASSADA'}</div>
      <div class="br-title">${o.win ? 'VITÓRIA' : 'DERROTA'}</div>
      <div class="br-sub">${o.targetName} · ${o.faction} · Setor nível ${o.level}</div>
      <div class="br-stats">
        <div class="br-stat"><small>PODER DE ATAQUE</small><b>${fmt(o.atk)}</b></div>
        <div class="br-stat"><small>DEFESA INIMIGA</small><b>${fmt(o.def)}</b></div>
        <div class="br-stat"><small>UNIDADES PERDIDAS</small><b class="${o.win ? '' : 'red'}">${fmt(o.lost)}</b></div>
        <div class="br-stat"><small>FERIDOS RECUPERADOS</small><b class="teal">${fmt(o.recoveredTotal)}</b></div>
      </div>
      ${o.win ? `<div class="br-loot">${loot}</div>` : '<p class="modal-note" style="margin:10px 0">Suas tropas restantes retornaram à base. Reforce o exército e tente novamente.</p>'}
      <div class="br-actions">
        <button class="btn ${o.win ? '' : 'ghost'}" data-b-action="continue"><svg class="ico"><use href="#i-${o.win ? 'flag' : 'shield'}"/></svg> ${o.win ? 'ASSUMIR O SETOR' : 'RETORNAR À BASE'}</button>
      </div>`;
  }

  finish() {
    if (this.done) return;
    this.done = true;
    const o = this.outcome;
    this.close();
    this.onFinish(o);
  }

  close() {
    this.active = false;
    this.resultShown = false;
    cancelAnimationFrame(this._raf);
    stopBattleAmbience();
    window.removeEventListener('resize', this._resize);
    this.root.hidden = true;
    this.root.innerHTML = '';
    this.canvas = null;
  }
}

function easeOut(t) { return 1 - Math.pow(1 - clamp(t, 0, 1), 3); }
function easeIn(t) { return Math.pow(clamp(t, 0, 1), 2); }

/* ============================================================
   Interface, painéis e modais — COMANDO GLOBAL
   ============================================================ */
import {
  BUILDING_DEFS, BUILDING_BY_KEY, UNIT_DEFS, UNIT_BY_KEY, TECH_DEFS, TECH_BY_KEY,
  HERO_DEFS, HERO_BY_KEY, HERO_SKILLS, TARGETS, TARGET_BY_ID, MISSIONS,
  RANKING, ALLIANCE_MEMBERS, CHAT_LINES, FACTION_COLORS, RESOURCES, RES_KEYS,
  fmt, fmtTime, fmtTimeShort, targetLoot, targetTravel, heroPortrait, clamp
} from './data.js';
import {
  state, subscribe, production, capacity, energyInfo, troopCap, troopPower, totalPower,
  conqueredCount, domination, marchSlots, targetState, targetOdds, buildingUpgradeInfo,
  queueForBuilding, buildingProductionNow, canAfford, missingResources, upgradeBuilding,
  collectBuilding, trainUnits, unitUnlocked, unlockRequirement, researchCost, researchTime,
  startResearch, selectHero, unlockHero, levelSkill, sendMarch, missionProgress, claimMission,
  resolveArrival, activeBattle, selectBuilding, selectTarget, setView, toggleSetting,
  buildingLevel, armyCount, queuedTroops
} from './state.js';
import {
  click, open, close, success, error, coin, buildStart, buildDone, march, alarm, levelUp, setSound, setMusic
} from './audio.js';

const $ = (sel, root = document) => root.querySelector(sel);
const $$ = (sel, root = document) => [...root.querySelectorAll(sel)];
const ico = (name, cls = '') => `<svg class="ico ${cls}" aria-hidden="true"><use href="#i-${name}"/></svg>`;
const byId = (id) => document.getElementById(id);
const isMobile = () => window.matchMedia('(max-width: 900px)').matches;

function resIcon(k) { return RESOURCES[k]?.icon || 'credit'; }
function resColor(k) { return RESOURCES[k]?.color || '#f2a63b'; }
function pct(a, b) { return clamp(Math.round((a / Math.max(1, b)) * 100), 0, 100); }

function costChips(cost) {
  return Object.entries(cost).map(([k, v]) => `
    <span class="cost-item ${state.resources[k] < v ? 'missing' : ''}" style="--rc:${resColor(k)}">
      ${ico(resIcon(k))}${fmt(v)}
    </span>`).join('');
}

function lootChips(loot) {
  return Object.entries(loot).filter(([, v]) => v > 0).map(([k, v]) => `
    <span class="loot-item" style="--rc:${resColor(k)}">${ico(resIcon(k))}+${fmt(v)}</span>`).join('');
}

function progressBar(start, finish, cls = '') {
  const now = Date.now();
  const p = clamp(((now - start) / Math.max(1, finish - start)) * 100, 0, 100);
  return `<div class="progress ${cls}"><i data-bar data-start="${start}" data-finish="${finish}" style="width:${p}%"></i></div>`;
}

function timerTag(finish, prefix = '') {
  return `<span class="btn-timer" data-finish="${finish}">${prefix}${fmtTime(finish - Date.now())}</span>`;
}

function heroName() { return HERO_BY_KEY[state.activeHero]?.name || 'COMANDANTE'; }

export class UI {
  constructor({ iso, world, battle }) {
    this.iso = iso;
    this.world = world;
    this.battle = battle;
    this.hudResources = byId('hud-resources');
    this.context = byId('context');
    this.dock = byId('dock');
    this.modalRoot = byId('modal-root');
    this.toasts = byId('toasts');
    this.battleRoot = byId('battle-root');
    this.chatFeed = byId('chat-feed');
    this.chatMessages = [];
    this.chatSeed = CHAT_LINES.length - 7;
    this.modalData = null;
    this.attack = null;
    this._lastHud = 0;
    this._toastSeq = 0;
    this.bindEvents();
    this.subscribeState();
    this.seedChat();
    this.renderAll();
    this.startIntervals();
  }

  /* ============================================================
     Eventos
     ============================================================ */
  bindEvents() {
    document.addEventListener('click', (e) => this.onClick(e));
    document.addEventListener('keydown', (e) => {
      if (e.key === 'Escape') {
        if (!$('#modal-root .modal')) return;
        this.closeModal();
      }
    });
    byId('rail').addEventListener('click', (e) => {
      const btn = e.target.closest('[data-view]');
      if (!btn) return;
      click();
      setView(btn.dataset.view);
    });
    this.iso.onSelect = (key) => {
      click();
      selectBuilding(key);
      this.iso.select(key);
      this.renderContext();
      if (isMobile()) this.openContext();
    };
    this.world.onSelect = (id) => {
      click();
      selectTarget(id);
      this.world.setSelected(id);
      this.renderContext();
      if (isMobile()) this.openContext();
    };
    this.battleRoot.addEventListener('click', () => { /* battle controla seus botões */ });
    this.chatFeed.addEventListener('click', () => {});
    window.addEventListener('resize', () => {
      if (state.view === 'base') this.iso.resize();
      if (state.view === 'world') this.world.resize();
    });
  }

  onClick(e) {
    const viewBtn = e.target.closest('[data-view]');
    if (viewBtn && !viewBtn.closest('#rail')) {
      e.preventDefault();
      setView(viewBtn.dataset.view);
      return;
    }
    const actEl = e.target.closest('[data-action]');
    if (!actEl) return;
    const act = actEl.dataset.action;
    const data = actEl.dataset;
    switch (act) {
      case 'toggle-sound': {
        const on = toggleSetting('sound');
        setSound(on);
        this.renderSound();
        this.showToast(on ? 'SOM ATIVADO' : 'SOM DESATIVADO', '', on ? 'good' : '');
        break;
      }
      case 'open-reports': this.openReports(); break;
      case 'open-settings': this.openSettings(); break;
      case 'open-more': this.openMore(); break;
      case 'close-modal': this.closeModal(); break;
      case 'close-context': this.closeContext(); break;
      case 'go-view': setView(data.view); this.closeContext(); break;
      case 'upgrade-building': {
        const res = upgradeBuilding(data.building);
        if (!res.ok) { error(); this.showToast('OPERAÇÃO BLOQUEADA', res.msg, 'bad'); }
        else { buildStart(); this.renderAll(); }
        break;
      }
      case 'collect-building': {
        const res = collectBuilding(data.building);
        if (res.ok) coin(); else { error(); this.showToast('COLETA INDISPONÍVEL', res.msg, 'bad'); }
        break;
      }
      case 'open-train': this.openTrain(data.unit); break;
      case 'quick-train': this.quickTrain(data.unit); break;
      case 'train-confirm': this.confirmTrain(); break;
      case 'qty-inc': this.changeQty(parseInt(data.delta, 10)); break;
      case 'qty-max': this.setMaxQty(); break;
      case 'research-tech': this.doResearch(data.tech); break;
      case 'claim-mission': {
        const res = claimMission(data.mission);
        if (res.ok) success(); else { error(); this.showToast('MISSÃO INCOMPLETA', res.msg, 'bad'); }
        break;
      }
      case 'select-hero': {
        const res = selectHero(data.hero);
        if (!res.ok) { error(); this.showToast('COMANDANTE BLOQUEADO', res.msg, 'bad'); }
        else open();
        break;
      }
      case 'unlock-hero': {
        const res = unlockHero(data.hero);
        if (!res.ok) { error(); this.showToast('RECRUTAMENTO BLOQUEADO', res.msg, 'bad'); }
        else { success(); this.renderAll(); }
        break;
      }
      case 'level-skill': {
        const res = levelSkill(data.skill);
        if (!res.ok) { error(); this.showToast('SEM PONTOS', res.msg, 'bad'); }
        else levelUp();
        break;
      }
      case 'attack-target': this.openAttack(data.target); break;
      case 'attack-confirm': this.confirmAttack(); break;
      case 'attack-qty': this.changeAttackQty(data.unit, parseInt(data.delta, 10)); break;
      case 'attack-max': this.maxAttack(data.unit); break;
      case 'world-center': {
        selectTarget(null);
        this.world.setSelected(null);
        this.renderContext();
        break;
      }
      case 'toggle-music': {
        const on = toggleSetting('music');
        setMusic(on);
        this.openSettings();
        break;
      }
      case 'reset-game': this.confirmReset(); break;
      case 'confirm-reset': {
        localStorage.removeItem('comando-global-save-v3');
        location.reload();
        break;
      }
      case 'open-reports-from-battle': this.openReports(); break;
      case 'show-battle': {
        const b = activeBattle();
        if (b) this.openBattle(b);
        break;
      }
      case 'dismiss-modal': this.closeModal(); break;
      default: break;
    }
  }

  subscribeState() {
    subscribe((type, payload) => {
      if (type === 'toast') this.showToast(payload.title, payload.text, payload.kind);
      if (type === 'change') this.onChange();
      if (type === 'tick') this.onTick();
      if (type === 'view') this.applyView(payload.view);
      if (type === 'select') this.renderContext();
      if (type === 'selectTarget') { this.world.setSelected(payload.id); this.renderContext(); }
      if (type === 'arrival') this.queueBattle(payload);
      if (type === 'complete') {
        if (state.view === 'base') this.iso.layout();
        this.world.refresh();
      }
      if (type === 'march') { march(); this.world.refresh(); this.renderDock(); }
    });
  }

  onChange() {
    this.renderHud();
    this.renderView();
    this.renderContext();
    this.renderDock();
    this.world.refresh();
    if (state.view === 'base') this.iso.layout();
  }

  onTick() {
    const now = Date.now();
    if (now - this._lastHud > 950) {
      this._lastHud = now;
      this.renderHud();
    }
    this.updateTimers();
    this.renderDock();
    if (state.view === 'base' || state.view === 'world') {
      if (!this._lastCtx || now - this._lastCtx > 1400) {
        this._lastCtx = now;
        this.renderContext();
      }
    }
  }

  /* ============================================================
     HUD / DOCK
     ============================================================ */
  renderHud() {
    const prod = production();
    this.hudResources.innerHTML = [...RES_KEYS, 'gems'].map((k) => {
      const r = RESOURCES[k];
      const amount = state.resources[k] || 0;
      const cap = capacity();
      const near = k !== 'gems' && amount >= cap * 0.96;
      return `<div class="res-chip" style="--rc:${r.color}" title="${r.name}${k !== 'gems' ? ` · capacidade ${fmt(cap)}` : ''}">
        <span class="res-ico">${ico(r.icon)}</span>
        <span class="res-info"><b class="${near ? 'red' : ''}">${fmt(amount)}</b>
        <small class="${k !== 'gems' ? 'rate' : ''}">${k === 'gems' ? 'DIAMANTES' : `+${fmt(prod[k])}/h`}</small></span>
      </div>`;
    }).join('');
    const energy = energyInfo();
    const eEl = byId('hud-energy');
    eEl.classList.toggle('deficit', energy.deficit);
    eEl.innerHTML = `${ico('bolt')}<b>${energy.free}</b>`;
    eEl.title = `Energia: ${energy.use}/${energy.prod} · ${energy.deficit ? 'déficit' : 'estável'}`;
    byId('hud-level').textContent = state.player.level;
    byId('hud-name').textContent = state.player.name;
    byId('hud-power').textContent = fmt(totalPower());
    const badge = byId('report-badge');
    const pending = state.reports.length + state.arrivals.length;
    badge.textContent = pending > 99 ? '99+' : pending;
    badge.dataset.zero = pending ? '0' : '1';
    this.renderSound();
  }

  renderSound() {
    const use = byId('sound-icon')?.querySelector('use');
    if (use) use.setAttribute('href', state.settings.sound ? '#i-volume' : '#i-mute');
  }

  renderDock() {
    if (!this.dock) return;
    const slots = [];
    const build = state.buildQueue[0];
    slots.push({
      kind: 'OBRAS', icon: 'home', cls: '',
      label: build ? `${BUILDING_BY_KEY[build.buildingKey].name} · Nv ${build.toLevel}` : 'Nenhuma obra em andamento',
      item: build, empty: 'ENGENHEIROS LIVRES', view: 'base',
      start: build?.startAt, finish: build?.finishAt, extra: state.buildQueue.length > 1 ? `+${state.buildQueue.length - 1}` : ''
    });
    const train = state.trainQueue[0];
    slots.push({
      kind: 'TREINAMENTO', icon: 'army', cls: 'teal',
      label: train ? `${train.qty}× ${UNIT_BY_KEY[train.unitKey].name}` : 'Quartel aguardando ordens',
      item: train, empty: 'FILA LIVRE', view: 'army',
      start: train?.startAt, finish: train?.finishAt, extra: state.trainQueue.length > 1 ? `+${state.trainQueue.length - 1}` : ''
    });
    const tech = state.researchQueue[0];
    slots.push({
      kind: 'PESQUISA', icon: 'flask', cls: 'blue',
      label: tech ? `${TECH_BY_KEY[tech.techKey].name} · Nv ${tech.toLevel}` : 'Laboratório em espera',
      item: tech, empty: 'LABORATÓRIO LIVRE', view: 'research',
      start: tech?.startAt, finish: tech?.finishAt,
    });
    const m = state.marches[0];
    const target = m ? TARGET_BY_ID[m.targetId] : null;
    slots.push({
      kind: 'MARCHAS', icon: 'sword', cls: 'red',
      label: m ? `Força → ${target.name}` : `${marchSlots()} frentes disponíveis`,
      item: m, empty: 'NENHUMA MARCHA', view: 'world',
      start: m?.sentAt, finish: m?.arriveAt, extra: state.marches.length > 1 ? `+${state.marches.length - 1}` : ''
    });
    this.dock.innerHTML = slots.map((s) => {
      if (!s.item) {
        return `<button class="dock-slot" data-view="${s.view}">
          <span class="dock-ico ${s.cls}">${ico(s.icon)}</span>
          <span class="dock-info"><small>${s.kind}</small><span class="dock-empty"><b>${s.empty}</b></span></span>
        </button>`;
      }
      return `<button class="dock-slot active" data-view="${s.view}">
        <span class="dock-ico ${s.cls}">${ico(s.icon)}</span>
        <span class="dock-info">
          <span class="dk-top"><small>${s.kind}</small><span class="dk-time" data-finish="${s.finish}">${fmtTime(s.finish - Date.now())}</span></span>
          <b>${s.label}</b>
          ${progressBar(s.start, s.finish, s.cls === 'teal' ? 'teal' : s.cls === 'red' ? 'red' : '')}
          ${s.extra ? `<span class="dock-more">${s.extra}</span>` : ''}
        </span>
      </button>`;
    }).join('');
  }

  updateTimers() {
    const now = Date.now();
    $$('[data-finish]').forEach((el) => {
      const finish = Number(el.dataset.finish);
      const left = finish - now;
      if (!Number.isFinite(finish)) return;
      el.textContent = left <= 0 ? 'PRONTO' : fmtTime(left);
      if (left <= 0) el.classList.add('ready');
    });
    $$('[data-bar]').forEach((el) => {
      const start = Number(el.dataset.start);
      const finish = Number(el.dataset.finish);
      if (!Number.isFinite(finish)) return;
      const p = clamp(((now - start) / Math.max(1, finish - start)) * 100, 0, 100);
      el.style.width = `${p}%`;
    });
  }

  /* ============================================================
     Painel de contexto
     ============================================================ */
  renderContext() {
    if (state.view !== 'base' && state.view !== 'world') {
      this.context.innerHTML = '';
      return;
    }
    this.context.innerHTML = state.view === 'base' ? this.baseContext() : this.worldContext();
    this.updateTimers();
  }

  baseContext() {
    const key = state.selectedBuilding || 'hq';
    const def = BUILDING_BY_KEY[key];
    if (!def) return '';
    const info = buildingUpgradeInfo(key);
    const lvl = info.level;
    const q = queueForBuilding(key);
    const prod = lvl > 0 ? buildingProductionNow(key) : null;
    const energy = energyInfo();
    const ready = def.prod && lvl > 0 && Date.now() >= (state.collect[key] || 0);
    const nextLocked = key !== 'hq' && lvl + 1 > buildingLevel('hq');
    const stat = (label, value, iconName) => `<div class="ctx-stat"><small>${label}</small><b>${iconName ? ico(iconName) : ''}${value}</b></div>`;
    let stats = '';
    if (prod) {
      stats = Object.entries(prod).map(([k, v]) => stat(RESOURCES[k].short, `+${fmt(v)}/h`, RESOURCES[k].icon)).join('');
      stats += stat('NÍVEL', `${lvl}<span class="muted"> / ${def.max}</span>`, 'up');
    } else if (def.key === 'hq') {
      stats = stat('NÍVEL', `${lvl}<span class="muted"> / ${def.max}</span>`, 'star')
        + stat('PRODUÇÃO GLOBAL', `+${lvl * 4}%`, 'bolt')
        + stat('OBRAS ATIVAS', `${state.buildQueue.length}/2`, 'home')
        + stat('COMANDANTE', `Nv ${state.player.level}`, 'medal');
    } else {
      stats = stat('NÍVEL', `${lvl}<span class="muted"> / ${def.max}</span>`, 'up')
        + stat('ENERGIA', def.powerGive ? `+${def.powerGive * lvl}` : `−${(def.powerUse || 0) * lvl}`, 'bolt')
        + stat('EFEITO', def.effect.replace(/^[−+-]?/, m => m), 'star')
        + stat('PODER', `+${lvl * 55}`, 'shield');
    }
    const queueBlock = q ? `
      <div class="ctx-effect" style="color:var(--gold-2)">${ico('clock')} ${q.kind === 'build' ? 'Construção' : 'Evolução'} para nível ${q.toLevel} ${timerTag(q.finish, '· ')}</div>
      ${progressBar(q.startAt, q.finishAt)}
    ` : '';

    let action = '';
    if (ready) {
      action = `<button class="btn full" data-action="collect-building" data-building="${key}">${ico('credit')} COLETAR RECURSOS</button>`;
    }
    if (q) {
      action += `<button class="btn full ghost" disabled style="margin-top:6px">${ico('clock')} EM OBRAS ${timerTag(q.finish, '· ')}</button>`;
    } else if (info.maxed) {
      action += `<button class="btn full ghost" disabled style="margin-top:6px">${ico('check')} NÍVEL MÁXIMO ALCANÇADO</button>`;
    } else if (nextLocked) {
      action += `<button class="btn full ghost" disabled style="margin-top:6px">${ico('lock')} REQUER QG NÍVEL ${lvl + 1}</button>`;
    } else {
      action += `<div class="cost-grid">${costChips(info.cost)}</div>
        <button class="btn full" data-action="upgrade-building" data-building="${key}">
          ${ico(lvl === 0 ? 'plus' : 'up')} ${lvl === 0 ? 'CONSTRUIR' : 'EVOLUIR PARA NÍVEL ' + (lvl + 1)}
          ${timerTag(Date.now() + info.time * 1000, '· ')}
        </button>`;
    }

    const objectives = MISSIONS.filter(m => !state.claimedMissions.includes(m.id)).slice(0, 3);
    const objHtml = objectives.map((m) => {
      const p = missionProgress(m.id);
      return `<button class="objective" data-action="go-view" data-view="campaign">
        <span class="ob-ico">${ico(p.done ? 'check' : 'target')}</span>
        <span class="ob-txt"><b>${m.name}</b><small>${p.text}</small></span>
        <span class="ob-go">${ico('arrow')}</span>
      </button>`;
    }).join('') || `<p class="ctx-footnote">Todos os objetivos concluídos. O planeta é seu.</p>`;

    return `
      <div class="ctx-card">
        <div class="ctx-eyebrow">${ico('target')} CENTRO DE COMANDO</div>
        <div class="ctx-head">
          <span class="ctx-icon">${ico(def.icon)}</span>
          <div class="ctx-name"><h2>${def.name}</h2><p>${def.tag} · ${lvl > 0 ? 'OPERACIONAL' : 'AGUARDANDO CONSTRUÇÃO'}</p></div>
          <span class="ctx-level">NV ${lvl}</span>
        </div>
        <div class="ctx-stats">${stats}</div>
        ${queueBlock}
        <p class="ctx-desc">${def.desc}</p>
        <div class="ctx-effect">${ico('bolt')} ${def.effect}</div>
        ${action}
        <div class="cost-grid" style="margin-top:8px">
          <span class="cost-item ${energy.deficit ? 'missing' : ''}">${ico('bolt')} ${energy.use}/${energy.prod} ENERGIA</span>
          <span class="cost-item">${ico('clock')} ${def.time}s BASE</span>
        </div>
      </div>
      <div class="ctx-card">
        <div class="ctx-eyebrow">${ico('flag')} OBJETIVOS ATIVOS</div>
        <div class="ctx-objectives">${objHtml}</div>
        <p class="ctx-footnote">${marchSlots()} frentes de marcha · ${state.buildQueue.length}/2 engenheiros · ${state.trainQueue.length}/3 filas de treino</p>
      </div>`;
  }

  worldContext() {
    const id = state.selectedTarget;
    const t = id ? targetState(id) : null;
    if (!t) {
      const openTargets = TARGETS.filter(x => !x.player && state.targets[x.id]?.owner !== 'player')
        .sort((a, b) => distanceToBase(a) - distanceToBase(b)).slice(0, 4);
      const rows = openTargets.map((x) => `
        <button class="objective" data-action="attack-target" data-target="${x.id}">
          <span class="ob-ico" style="color:${FACTION_COLORS[x.faction]};border-color:${FACTION_COLORS[x.faction]}55;background:${FACTION_COLORS[x.faction]}12">${ico('flag')}</span>
          <span class="ob-txt"><b>${x.name}</b><small>${x.faction} · DEF ${fmt(x.def)} · ${targetTravel(x)}s</small></span>
          <span class="ob-go">${ico('sword')}</span>
        </button>`).join('');
      return `
        <div class="ctx-card">
          <div class="ctx-eyebrow">${ico('map')} TEATRO DE GUERRA</div>
          <div class="dom-row"><div><small>DOMÍNIO MUNDIAL</small><b>${domination()}%</b></div><div style="text-align:right"><small>SETORES</small><b>${conqueredCount()}/17</b></div></div>
          ${progressBar(0, 1)}
          <p class="ctx-desc">Conquiste setores no mapa para aumentar sua produção global, receber tributos de guerra e liberar novas frentes de ataque.</p>
          <div class="ctx-effect" style="color:var(--teal)">${ico('bolt')} +${(conqueredCount() * 3)}% de produção global</div>
          <div class="cost-grid"><span class="cost-item">${ico('flag')} +${(conqueredCount() * 1.5).toFixed(1)}%/h de tributo</span><span class="cost-item">${ico('sword')} ${state.marches.length}/${marchSlots()} marchas</span></div>
        </div>
        <div class="ctx-card">
          <div class="ctx-eyebrow">${ico('target')} ALVOS PRÓXIMOS</div>
          <div class="ctx-objectives">${rows || '<p class="ctx-footnote">Todos os setores foram dominados.</p>'}</div>
          <p class="ctx-footnote">Selecione um marcador no mapa para ver defesa, espólio e probabilidade de vitória.</p>
        </div>`;
    }
    if (t.player) {
      return `
        <div class="ctx-card">
          <div class="ctx-eyebrow">${ico('crown')} SUA FORTALEZA</div>
          <div class="ctx-head">
            <span class="ctx-icon" style="color:var(--teal);border-color:rgba(69,211,198,.4)">${ico('crown')}</span>
            <div class="ctx-name"><h2>${t.name}</h2><p>${t.faction} · CAPITAL</p></div>
            <span class="ctx-level">NV ${t.level}</span>
          </div>
          <div class="ctx-stats">
            <div class="ctx-stat"><small>PODER TOTAL</small><b>${fmt(totalPower())}</b></div>
            <div class="ctx-stat"><small>EXÉRCITO</small><b>${fmt(armyCount())}/${fmt(troopCap())}</b></div>
            <div class="ctx-stat"><small>SETORES</small><b>${conqueredCount()}/17</b></div>
            <div class="ctx-stat"><small>MARCHAS</small><b>${state.marches.length}/${marchSlots()}</b></div>
          </div>
          <p class="ctx-desc">Seu quartel-general no mapa mundial. Proteja a fortaleza evoluindo a Muralha de Aço e o Hospital de Campanha.</p>
          <button class="btn full" data-action="go-view" data-view="base">${ico('home')} VOLTAR À BASE</button>
        </div>`;
    }
    const conquer = t.owner === 'player';
    const odds = targetOdds(t.id, state.troops);
    const oddsPct = Math.min(999, odds.percent);
    const oddsColor = oddsPct >= 100 ? 'var(--teal)' : oddsPct >= 70 ? 'var(--gold)' : 'var(--red)';
    const loot = targetLoot(t);
    const marches = state.marches.filter(m => m.targetId === t.id);
    return `
      <div class="ctx-card">
        <div class="ctx-eyebrow">${ico(conquer ? 'check' : 'flag')} ${conquer ? 'SETOR DOMINADO' : 'ALVO HOSTIL'}</div>
        <div class="ctx-head">
          <span class="ctx-icon" style="color:${FACTION_COLORS[t.faction]};border-color:${FACTION_COLORS[t.faction]}55">${ico(conquer ? 'flag' : 'target')}</span>
          <div class="ctx-name"><h2>${t.name}</h2><p>${t.faction}</p></div>
          <span class="ctx-level" style="color:${FACTION_COLORS[t.faction]};border-color:${FACTION_COLORS[t.faction]}55">NV ${t.level}</span>
        </div>
        <div class="target-faction">${ico('map-pin')} SETOR ${t.id.replace('t', '')} · ${targetTravel(t)}s DE MARCHA</div>
        <div class="ctx-stats">
          <div class="ctx-stat"><small>DEFESA</small><b>${fmt(t.def)}</b></div>
          <div class="ctx-stat"><small>SEU PODER</small><b>${fmt(odds.atk)}</b></div>
          <div class="ctx-stat"><small>PROBABILIDADE</small><b style="color:${oddsColor}">${oddsPct}%</b></div>
          <div class="ctx-stat"><small>ESPÓLIO</small><b>${fmt(Object.values(loot).reduce((a, b) => a + b, 0))}</b></div>
        </div>
        <div class="odds">
          <span class="odds-label">FORÇA DE ATAQUE × DEFESA</span>
          <span class="odo-bar"><i style="width:${clamp(oddsPct, 0, 100)}%;background:${oddsColor}"></i></span>
          <b style="color:${oddsColor}">${oddsPct}%</b>
        </div>
        <div class="loot-row">${lootChips(loot)}</div>
        ${marches.map(m => `<div class="ctx-effect" style="color:var(--teal)">${ico('sword')} ${Object.values(m.units).reduce((a, b) => a + b, 0)} unidades a caminho ${timerTag(m.arriveAt, '· ')}</div>`).join('')}
        ${conquer
          ? `<div class="ctx-effect" style="color:var(--teal)">${ico('check')} Tributo ativo · produção global reforçada</div>
             <button class="btn full ghost" data-action="world-center">${ico('map')} ESCOLHER NOVO ALVO</button>`
          : `<button class="btn full" data-action="attack-target" data-target="${t.id}" ${conquer ? 'disabled' : ''}>${ico('sword')} MOBILIZAR ATAQUE</button>`}
        <p class="ctx-footnote">${conquer ? 'Este setor agora produz tributos para sua nação.' : 'A probabilidade usa todo o seu exército disponível. Você pode escolher menos tropas na tela de ataque.'}</p>
      </div>
      <div class="ctx-card">
        <div class="ctx-eyebrow">${ico('army')} INTELIGÊNCIA DO SETOR</div>
        <p class="ctx-desc" style="margin-top:0">${t.faction} mantém ${fmt(t.def)} pontos de defesa. ${oddsPct >= 100 ? 'Seu exército tem vantagem decisiva neste alvo.' : oddsPct >= 70 ? 'A batalha será dura. Reforce o ataque antes de marchar.' : 'A defesa supera sua força atual. Treine mais tropas e pesquise tecnologias militares.'}</p>
        <div class="cost-grid">
          <span class="cost-item">${ico('shield')} ${t.faction}</span>
          <span class="cost-item">${ico('target')} ${Math.round(t.def / 100)} defesa/100</span>
        </div>
        <button class="btn full ghost" data-action="go-view" data-view="army">${ico('army')} REFORÇAR EXÉRCITO</button>
      </div>`;
  }

  /* ============================================================
     Views
     ============================================================ */
  applyView(view) {
    this.game = byId('game');
    $$('#main .view').forEach(v => v.classList.toggle('active', v.id === `view-${view}`));
    $$('#rail .rail-btn[data-view]').forEach(b => b.classList.toggle('active', b.dataset.view === view));
    const wide = !['base', 'world'].includes(view);
    this.game.classList.toggle('wide', wide);
    this.closeContext();
    if (view === 'base') {
      this.iso.start();
      requestAnimationFrame(() => this.iso.resize());
    } else {
      this.iso.stop();
    }
    if (view === 'world') {
      this.world.start();
      requestAnimationFrame(() => { this.world.resize(); this.world.refresh(); });
    } else {
      this.world.stop();
    }
    this.renderView();
    this.renderContext();
  }

  renderView() {
    const view = state.view;
    if (view === 'army') byId('view-army').innerHTML = this.armyView();
    if (view === 'research') byId('view-research').innerHTML = this.researchView();
    if (view === 'campaign') byId('view-campaign').innerHTML = this.campaignView();
    if (view === 'hero') byId('view-hero').innerHTML = this.heroView();
    if (view === 'alliance') byId('view-alliance').innerHTML = this.allianceView();
  }

  renderAll() {
    this.renderHud();
    this.renderDock();
    this.renderView();
    this.renderContext();
    this.world.refresh();
    if (state.view === 'base') this.iso.layout();
  }

  armyView() {
    const cap = troopCap();
    const total = armyCount();
    const queued = queuedTroops();
    const q = state.trainQueue[0];
    const cards = UNIT_DEFS.map((u) => {
      const unlocked = unitUnlocked(u.key);
      const count = state.troops[u.key] || 0;
      const maxQty = this.maxTrainable(u.key);
      return `<article class="unit-card">
        <div class="unit-top">
          <span class="unit-icon">${ico(u.icon)}</span>
          <div class="unit-name"><h3>${u.name}</h3><span>${u.role}</span></div>
          <div class="unit-count"><b>${fmt(count)}</b><small>UNIDADES</small></div>
        </div>
        <div class="unit-stats">
          <div class="unit-stat"><small>ATAQUE</small><b>${u.attack}</b></div>
          <div class="unit-stat"><small>CUSTO</small><b>${Object.entries(u.cost).map(([k, v]) => `${fmt(v)}${k === 'food' ? 'A' : k === 'steel' ? 'AÇ' : k === 'oil' ? 'P' : 'C'}`).join(' ')}</b></div>
          <div class="unit-stat"><small>TEMPO / 10</small><b>${ico('clock')}${u.timePer10}s</b></div>
