        <div class="vh-stats">
          <div class="vh-stat"><small>EFETIVO</small><b>${fmt(total)}</b></div>
          <div class="vh-stat"><small>CAPACIDADE</small><b>${fmt(cap)}</b></div>
          <div class="vh-stat"><small>PODER DE TROPA</small><b>${fmt(troopPower())}</b></div>
