        <p class="tech-desc">${t.effect}</p>
        <div class="tech-effect">${lvl > 0 ? `BÔNUS ATUAL: ${(lvl * parseFloat(t.effect.match(/[+\-−]?([\d.]+)%/)?.[1] || 0)).toFixed(0)}%` : 'AINDA NÃO PESQUISADO'}</div>
