import {
  SAVE_KEY, GAME_VERSION, BUILDING_DEFS, BUILDING_BY_KEY, UNIT_DEFS, UNIT_BY_KEY,
  TECH_DEFS, TECH_BY_KEY, HERO_DEFS, HERO_BY_KEY, TARGETS, TARGET_BY_ID,
