      </div>`;
  }

  finish() {
    if (this.done) return;
    this.done = true;
    const o = this.outcome;
    this.close();
    this.onFinish(o);
  }

  close() {
    this.active = false;
    this.resultShown = false;
    cancelAnimationFrame(this._raf);
    stopBattleAmbience();
    window.removeEventListener('resize', this._resize);
    this.root.hidden = true;
    this.root.innerHTML = '';
    this.canvas = null;
  }
}

