function ridgePath(rng, w, baseY, amp, step, bottom) {
  const pts = [[-20, bottom]];
  let x = -20;
  let y = baseY;
  while (x < w + 40) {
    y = baseY - rng() * amp - Math.sin(x * 0.011) * amp * 0.22;
    pts.push([x, y]);
    x += step * (0.55 + rng() * 0.9);
  }
  pts.push([w + 20, bottom]);
  return pts;
}

class TitleScene {
  constructor(canvas) {
    this.canvas = canvas;
    this.ctx = canvas.getContext('2d');
    this.running = false;
    this.t = 0;
    this._raf = 0;
    this._last = 0;
    this.dpr = 1;
    this.w = 1;
    this.h = 1;
    this._ro = new ResizeObserver(() => this.resize());
    this._ro.observe(canvas);
    this.resize();
  }

  resize() {
    const rect = this.canvas.getBoundingClientRect();
    const w = Math.max(1, rect.width || window.innerWidth);
    const h = Math.max(1, rect.height || window.innerHeight);
    this.dpr = Math.min(2, window.devicePixelRatio || 1);
    this.canvas.width = Math.round(w * this.dpr);
    this.canvas.height = Math.round(h * this.dpr);
    this.ctx.setTransform(this.dpr, 0, 0, this.dpr, 0, 0);
    this.w = w;
    this.h = h;
    this.layout();
  }

  layout() {
    const { w, h } = this;
    const rng = rnd(0x0c0d3a7);
    this.stars = Array.from({ length: Math.round(clamp(w / 8, 60, 190)) }, () => ({
      x: rng() * w,
      y: rng() * h * 0.56,
      r: 0.35 + rng() * 1.15,
      a: 0.18 + rng() * 0.7,
      tw: rng() * Math.PI * 2,
      speed: 0.35 + rng() * 1.4
    }));
    this.dust = Array.from({ length: Math.round(clamp(w / 14, 36, 110)) }, () => ({
      x: rng() * w,
      y: h * (0.5 + rng() * 0.55),
      r: 0.6 + rng() * 1.7,
      speed: 4 + rng() * 16,
      drift: (rng() - 0.5) * 14,
      a: 0.1 + rng() * 0.45,
      ph: rng() * Math.PI * 2
    }));
    this.embers = Array.from({ length: Math.round(clamp(w / 34, 14, 46)) }, () => ({
      x: rng() * w,
      y: h * (0.62 + rng() * 0.4),
      r: 0.7 + rng() * 1.8,
      speed: 12 + rng() * 32,
      drift: (rng() - 0.5) * 34,
      a: 0.25 + rng() * 0.55,
      ph: rng() * Math.PI * 2
    }));
    this.backRidge = ridgePath(rng, w, h * 0.628, h * 0.075, 34, h);
    this.midRidge = ridgePath(rng, w, h * 0.674, h * 0.052, 26, h);
    this.frontRidge = ridgePath(rng, w, h * 0.716, h * 0.032, 20, h);
    this.lights = Array.from({ length: Math.round(clamp(w / 40, 18, 54)) }, () => ({
      x: rng() * w,
      y: h * (0.695 + rng() * 0.025),
      a: 0.2 + rng() * 0.55,
      s: 0.7 + rng() * 1.2,
      ph: rng() * Math.PI * 2
    }));
    this.smokeSeeds = [0.16, 0.38, 0.72, 0.88].map((x, i) => ({
      x: w * x,
      y: h * (0.64 + (i % 2) * 0.03),
      w: 26 + (i % 3) * 16,
      drift: (i % 2 ? -1 : 1) * (5 + i * 2),
      ph: i * 1.7
    }));
    const planeRng = rnd(0x71a3);
    this.planes = [
      { x: -0.2, y: 0.2, v: 0.016, s: 1, d: 1 },
      { x: 0.45, y: 0.31, v: 0.011, s: 0.7, d: 1 },
      { x: 0.9, y: 0.14, v: -0.008, s: 0.55, d: -1 }
    ].map((p, i) => ({ ...p, ph: planeRng() * 10, blink: i * 1.7 }));
  }

  start() {
    if (this.running) return;
    this.running = true;
    this._last = performance.now();
    const loop = (now) => {
      if (!this.running) return;
      const dt = Math.min(64, now - this._last);
      this._last = now;
      this.t += dt;
      this.draw(dt);
      this._raf = requestAnimationFrame(loop);
    };
    this._raf = requestAnimationFrame(loop);
  }

  stop() {
    this.running = false;
    cancelAnimationFrame(this._raf);
  }

  draw(dt) {
    const c = this.ctx;
    const { w, h } = this;
    const t = this.t;
    c.clearRect(0, 0, w, h);

    // --- céu profundo -------------------------------------------------
    const sky = c.createLinearGradient(0, 0, 0, h);
    sky.addColorStop(0, '#03060a');
    sky.addColorStop(0.34, '#071019');
    sky.addColorStop(0.58, '#101c29');
    sky.addColorStop(0.74, '#1d2630');
    sky.addColorStop(1, '#080b0f');
    c.fillStyle = sky;
    c.fillRect(0, 0, w, h);

    // estrelas
    for (const s of this.stars) {
      const tw = 0.62 + Math.sin(t * 0.0009 * s.speed + s.tw) * 0.38;
      c.globalAlpha = s.a * tw;
      c.fillStyle = '#d9ecff';
      c.beginPath();
      c.arc(s.x, s.y, s.r, 0, Math.PI * 2);
      c.fill();
      if (s.r > 1.1) {
        c.globalAlpha *= 0.28;
        c.fillRect(s.x - s.r * 3, s.y - 0.35, s.r * 6, 0.7);
        c.fillRect(s.x - 0.35, s.y - s.r * 3, 0.7, s.r * 6);
      }
    }
    c.globalAlpha = 1;

    // brilho atmosférico no horizonte
    const haze = c.createRadialGradient(w * 0.68, h * 0.69, 0, w * 0.68, h * 0.69, w * 0.7);
    haze.addColorStop(0, 'rgba(242,146,54,.24)');
    haze.addColorStop(0.32, 'rgba(206,96,34,.10)');
    haze.addColorStop(0.72, 'rgba(80,40,30,.03)');
    haze.addColorStop(1, 'rgba(0,0,0,0)');
    c.fillStyle = haze;
    c.fillRect(0, h * 0.35, w, h * 0.65);

    // --- planeta no horizonte ---------------------------------------
    const pcx = w * 0.5;
    const pcy = h * 1.62;
    const pr = Math.min(w * 0.72, h * 1.04);
    const planet = c.createLinearGradient(0, pcy - pr, 0, pcy);
    planet.addColorStop(0, '#1b2833');
    planet.addColorStop(0.35, '#101a23');
    planet.addColorStop(0.72, '#0a1219');
    planet.addColorStop(1, '#05080c');
    c.fillStyle = planet;
    c.beginPath();
    c.arc(pcx, pcy, pr, 0, Math.PI * 2);
    c.fill();

    // detalhes de superfície do planeta
    c.save();
    c.beginPath();
    c.arc(pcx, pcy, pr, 0, Math.PI * 2);
    c.clip();
    c.globalAlpha = 0.28;
    c.strokeStyle = 'rgba(122,164,190,.22)';
    c.lineWidth = 1;
    for (let i = 0; i < 9; i++) {
      const yy = h * 0.62 + i * h * 0.058;
      c.beginPath();
      c.moveTo(0, yy);
      for (let x = 0; x <= w; x += 40) {
        c.lineTo(x, yy + Math.sin(x * 0.006 + i * 1.3 + t * 0.00006) * 4);
      }
      c.stroke();
    }
    c.globalAlpha = 1;
    // luzes de cidades no limbo
    for (const l of this.lights) {
      const flick = 0.55 + Math.sin(t * 0.0016 + l.ph) * 0.45;
      c.globalAlpha = l.a * flick;
      c.fillStyle = '#ffbf6a';
      c.fillRect(l.x, l.y, l.s, l.s * 0.55);
    }
    c.restore();

    // halo / borda iluminada
    c.save();
    c.strokeStyle = 'rgba(255,178,82,.82)';
    c.lineWidth = 2.1;
    c.shadowColor = 'rgba(255,152,54,.65)';
    c.shadowBlur = 26;
    c.beginPath();
    c.arc(pcx, pcy, pr, Math.PI * 1.06, Math.PI * 1.94);
    c.stroke();
    c.restore();

    // reflexo/limbo superior
    const rim = c.createLinearGradient(0, h * 0.6, 0, h * 0.8);
    rim.addColorStop(0, 'rgba(255,196,112,0)');
    rim.addColorStop(0.5, 'rgba(255,192,108,.10)');
    rim.addColorStop(1, 'rgba(255,180,92,0)');
    c.fillStyle = rim;
    c.fillRect(0, h * 0.6, w, h * 0.2);

    // --- cordilheira distante ---------------------------------------
    this.drawRidge(this.backRidge, '#17222c', '#2b3944', 0.5);
    this.drawRidge(this.midRidge, '#0c141c', 'rgba(186,116,58,.30)', 0.6);

    // torres de rádio distantes
    this.drawTower(w * 0.06, h * 0.70, h * 0.1, 0.55);
    this.drawTower(w * 0.93, h * 0.69, h * 0.14, 0.4);

    // --- bases e veículos em silhueta -------------------------------
    this.drawOutpost(w * 0.115, h * 0.79, Math.min(1.2, w / 1250), t, 1);
    this.drawOutpost(w * 0.885, h * 0.80, Math.min(1.2, w / 1250), t, -1);
    this.drawVehicle(w * 0.27, h * 0.845, 0.9, t, 1);
    this.drawVehicle(w * 0.71, h * 0.858, 1.15, t, -1);

    // fumaça de guerra
    for (const s of this.smokeSeeds) this.drawSmoke(s, t);

    // --- primeiro plano ---------------------------------------------
    const ground = c.createLinearGradient(0, h * 0.72, 0, h);
    ground.addColorStop(0, 'rgba(6,9,12,.72)');
    ground.addColorStop(0.3, '#05080b');
    ground.addColorStop(1, '#020406');
    c.fillStyle = ground;
    c.fillRect(0, h * 0.735, w, h * 0.265);

    this.drawRidge(this.frontRidge, '#05080b', 'rgba(255,162,70,.26)', 0.8);

    // faixas de pista iluminadas
    this.drawRunway(w * 0.5, h * 0.958, w * 0.62, t);

    // holofotes varrendo o céu
    this.drawSearchlight(w * 0.12, h * 0.86, -0.5 + Math.sin(t * 0.00018) * 0.32, t);
    this.drawSearchlight(w * 0.88, h * 0.86, 0.5 + Math.sin(t * 0.00014 + 1.6) * 0.3, t);

    // aeronaves
    for (const p of this.planes) this.drawPlane(p, t);

    // partículas / brasas
    for (const d of this.dust) {
      const y = (d.y - t * 0.001 * d.speed) % (h * 1.1);
      const yy = y < 0 ? y + h * 1.1 : y;
      c.globalAlpha = d.a * (0.45 + Math.sin(t * 0.001 + d.ph) * 0.35);
      c.fillStyle = '#b9d9ee';
      c.beginPath();
      c.arc((d.x + Math.sin(t * 0.0005 + d.ph) * 18 + t * 0.002 * d.drift) % w, yy, d.r, 0, Math.PI * 2);
      c.fill();
    }
    for (const e of this.embers) {
      const y = (e.y - t * 0.001 * e.speed) % (h * 0.9);
      const yy = y < h * 0.35 ? y + h * 0.9 : y;
      c.globalAlpha = e.a * (0.35 + Math.sin(t * 0.002 + e.ph) * 0.3);
      c.fillStyle = '#ff9d42';
      c.beginPath();
      c.arc((e.x + Math.sin(t * 0.0007 + e.ph) * 22 + t * 0.003 * e.drift) % w, yy, e.r, 0, Math.PI * 2);
      c.fill();
    }
    c.globalAlpha = 1;

    // linha de varredura
    const scanY = (t * 0.028) % (h + 160) - 80;
    const scan = c.createLinearGradient(0, scanY - 60, 0, scanY + 60);
    scan.addColorStop(0, 'rgba(120,200,225,0)');
    scan.addColorStop(0.5, 'rgba(120,200,225,.028)');
    scan.addColorStop(1, 'rgba(120,200,225,0)');
    c.fillStyle = scan;
    c.fillRect(0, scanY - 60, w, 120);

    // grade tática discreta na base da tela
    c.save();
    c.globalAlpha = 0.10;
    c.strokeStyle = 'rgba(120,180,210,.5)';
    c.lineWidth = 1;
    const gy = h * 0.87;
    for (let i = 0; i < 9; i++) {
      const y = gy + i * i * 2.4;
      c.beginPath();
      c.moveTo(0, y);
      c.lineTo(w, y);
      c.stroke();
    }
    for (let i = -12; i <= 12; i++) {
      c.beginPath();
      c.moveTo(w / 2 + i * w * 0.055, gy);
      c.lineTo(w / 2 + i * w * 0.16, h);
      c.stroke();
    }
    c.restore();

    // vinheta de calor no centro inferior
    c.globalAlpha = 1;
  }

  drawRidge(pts, fill, stroke, strokeAlpha) {
    const c = this.ctx;
    c.beginPath();
    c.moveTo(pts[0][0], pts[0][1]);
    for (let i = 1; i < pts.length; i++) c.lineTo(pts[i][0], pts[i][1]);
    c.closePath();
    c.fillStyle = fill;
    c.fill();
    if (stroke) {
      c.save();
      c.globalAlpha = strokeAlpha;
      c.strokeStyle = stroke;
      c.lineWidth = 1;
      c.beginPath();
      c.moveTo(pts[1][0], pts[1][1]);
      for (let i = 2; i < pts.length - 1; i++) c.lineTo(pts[i][0], pts[i][1]);
      c.stroke();
      c.restore();
    }
  }

  drawTower(x, baseY, height, alpha) {
    const c = this.ctx;
    c.save();
    c.globalAlpha = alpha;
    c.strokeStyle = '#0a1118';
    c.lineWidth = 2;
    c.beginPath();
    c.moveTo(x - 7, baseY);
    c.lineTo(x, baseY - height);
    c.lineTo(x + 7, baseY);
    c.stroke();
    c.lineWidth = 1;
    const blink = 0.35 + Math.sin(this.t * 0.003 + x) * 0.65;
    c.globalAlpha = alpha * blink;
    c.fillStyle = '#ff5c45';
    c.beginPath();
    c.arc(x, baseY - height - 2, 1.8, 0, Math.PI * 2);
    c.fill();
    c.restore();
  }

  drawOutpost(x, y, s, t, dir) {
    const c = this.ctx;
    c.save();
    c.translate(x, y);
    c.scale(s * dir, s);
    c.fillStyle = '#04070a';
    c.strokeStyle = 'rgba(140,180,205,.22)';
    c.lineWidth = 1;
    // torre de vigilância
    c.fillRect(-30, -52, 8, 52);
    c.fillRect(20, -52, 8, 52);
    c.fillRect(-34, -58, 36, 10);
    c.fillRect(-18, -68, 38, 10);
    c.strokeRect(-34, -78, 30, 10);
    // mastro
    c.beginPath();
    c.moveTo(8, -64);
    c.lineTo(8, -112);
    c.stroke();
    c.beginPath();
    c.moveTo(-8, -96);
    c.lineTo(8, -104);
    c.lineTo(24, -96);
    c.stroke();
    // radar girando
    c.save();
    c.translate(-20, -84);
    c.rotate(Math.sin(t * 0.0005) * 0.4 - 0.15);
    c.beginPath();
    c.ellipse(0, 0, 20, 7, 0, 0, Math.PI * 2);
    c.stroke();
    c.fillRect(-1, 0, 2, 10);
    c.restore();
    // sacos e caixas
    c.fillRect(-52, -18, 22, 18);
    c.fillRect(-44, -28, 14, 10);
    c.fillRect(34, -22, 26, 22);
    // luz de alerta
    const blink = 0.25 + Math.sin(t * 0.0022 + x) * 0.55;
    c.globalAlpha = blink;
    c.fillStyle = '#ff6a48';
    c.beginPath();
    c.arc(8, -115, 2.4, 0, Math.PI * 2);
    c.fill();
    c.restore();
  }

  drawVehicle(x, y, s, t, dir) {
    const c = this.ctx;
    c.save();
    c.translate(x + Math.sin(t * 0.00012 + x) * 5, y);
    c.scale(s * dir, s);
    c.fillStyle = '#030609';
    c.strokeStyle = 'rgba(120,160,185,.18)';
    c.lineWidth = 1;
    // esteiras
    c.fillRect(-42, -14, 84, 16);
    c.fillRect(-42, -5, 84, 7);
    for (let i = 0; i < 7; i++) c.fillRect(-38 + i * 12, -13, 2, 15);
    // casco
    c.beginPath();
    c.moveTo(-34, -14);
    c.lineTo(-26, -27);
    c.lineTo(18, -27);
    c.lineTo(34, -14);
    c.closePath();
    c.fill();
    // torre e canhão
    c.fillRect(-12, -36, 28, 10);
    c.fillRect(12, -33, 40, 3.2);
    c.fillRect(-22, -33, 8, 3);
    // antena
    c.beginPath();
    c.moveTo(-4, -36);
    c.lineTo(-4, -48);
    c.stroke();
    const blink = 0.3 + Math.sin(t * 0.002 + y) * 0.7;
    c.globalAlpha = blink;
    c.fillStyle = '#ffb457';
    c.beginPath();
    c.arc(-4, -50, 1.4, 0, Math.PI * 2);
    c.fill();
    c.restore();
  }

  drawSmoke(seed, t) {
    const c = this.ctx;
    const { h } = this;
    c.save();
    for (let i = 0; i < 17; i++) {
      const p = ((t * 0.000026 + i * 0.058 + seed.ph * 0.03) % 1);
      const r = seed.w * (0.35 + p * 2.6);
      const x = seed.x + Math.sin(p * 5 + seed.ph) * 18 + p * seed.drift * 12;
      const y = seed.y - p * h * 0.42;
      const a = (1 - p) * 0.20 * clamp(p * 9, 0, 1);
      const g = c.createRadialGradient(x, y, 0, x, y, r);
      g.addColorStop(0, `rgba(48,48,46,${a})`);
      g.addColorStop(0.5, `rgba(34,38,40,${a * 0.55})`);
      g.addColorStop(1, 'rgba(20,24,28,0)');
      c.fillStyle = g;
      c.beginPath();
      c.arc(x, y, r, 0, Math.PI * 2);
      c.fill();
    }
    c.restore();
  }

  drawRunway(cx, y, width, t) {
    const c = this.ctx;
    c.save();
    c.globalAlpha = 0.55;
    c.strokeStyle = 'rgba(255,176,82,.16)';
    c.lineWidth = 1;
    for (let i = -1; i <= 1; i += 2) {
      c.beginPath();
      c.moveTo(cx + i * width * 0.22, y);
      c.lineTo(cx + i * width * 0.5, this.h);
      c.stroke();
    }
    for (let i = 0; i < 8; i++) {
      const p = ((t * 0.00007 + i * 0.11) % 1);
      const yy = y + p * (this.h - y);
      c.globalAlpha = (1 - p) * 0.55;
      c.fillStyle = '#ffb45c';
      c.fillRect(cx - 1.5, yy, 3, 7 + p * 20);
    }
    c.restore();
  }

  drawSearchlight(x, y, angle, t) {
    const c = this.ctx;
    const len = this.h * 0.9;
    c.save();
    c.translate(x, y);
    c.rotate(angle);
    const g = c.createLinearGradient(0, 0, 0, -len);
    g.addColorStop(0, 'rgba(210,230,245,.12)');
    g.addColorStop(0.45, 'rgba(160,200,225,.045)');
    g.addColorStop(1, 'rgba(140,190,220,0)');
    c.fillStyle = g;
    c.beginPath();
    c.moveTo(-4, 0);
    c.lineTo(-len * 0.16, -len);
    c.lineTo(len * 0.16, -len);
    c.lineTo(4, 0);
    c.closePath();
    c.fill();
    c.fillStyle = 'rgba(220,240,255,.4)';
    c.beginPath();
    c.arc(0, 0, 2.4, 0, Math.PI * 2);
    c.fill();
    c.restore();
  }

  drawPlane(p, t) {
    const c = this.ctx;
    const { w, h } = this;
    const x = p.d > 0
      ? ((p.x + t * 0.00001 * p.v * 1000) % 1.4 - 0.2) * w
      : ((p.x - t * 0.00001 * Math.abs(p.v) * 1000) % 1.4 + 0.2) * w;
    const xx = p.d > 0 ? (((t * 0.00002 + p.ph) * p.v * 1000 + p.x) % 1.5 - 0.25) * w : x;
    const y = h * p.y + Math.sin(t * 0.0002 + p.ph) * 3;
    c.save();
    c.translate(xx, y);
    c.scale(p.s * p.d, p.s);
    c.translate(0, 0);
    const alpha = 0.5;
    c.globalAlpha = alpha;
    c.fillStyle = '#111a22';
    c.beginPath();
    c.moveTo(-18, 0);
    c.lineTo(8, -2.2);
    c.lineTo(18, 0);
    c.lineTo(8, 2.2);
    c.closePath();
    c.fill();
    c.fillRect(-5, -1, 14, 2);
    c.beginPath();
    c.moveTo(-5, 0);
    c.lineTo(-14, -9);
    c.lineTo(-9, -9);
    c.lineTo(1, 0);
    c.closePath();
    c.fill();
    c.beginPath();
    c.moveTo(-5, 0);
    c.lineTo(-14, 9);
    c.lineTo(-9, 9);
    c.lineTo(1, 0);
    c.closePath();
    c.fill();
    // rastro
    const trail = c.createLinearGradient(-80, 0, -12, 0);
    trail.addColorStop(0, 'rgba(180,205,220,0)');
    trail.addColorStop(1, 'rgba(180,205,220,.10)');
    c.fillStyle = trail;
    c.fillRect(-86, -1, 74, 2);
    // luz de navegação
    const blink = Math.sin(t * 0.003 + p.blink) > 0.3 ? 1 : 0.12;
    c.globalAlpha = blink;
    c.fillStyle = '#ff3b2f';
    c.beginPath();
    c.arc(-13, -8, 1.5, 0, Math.PI * 2);
    c.fill();
    c.fillStyle = '#4fe0a0';
    c.beginPath();
    c.arc(-13, 8, 1.5, 0, Math.PI * 2);
    c.fill();
    c.restore();
  }
}

