/* ============================ RESPONSIVE ============================ */
@media (max-width:1240px){
  :root{--ctx-w:320px}
  .res-chip{min-width:90px;padding-right:7px}
  .res-info small{display:none}
  .hud-energy{display:none}
}
@media (max-width:1080px){
  :root{--ctx-w:300px;--rail-w:76px}
  .hud-id{display:none}
  .hud-player{min-width:auto}
  .stage-legend{display:none}
  .hero-layout{grid-template-columns:300px minmax(0,1fr)}
}
@media (max-width:900px){
  :root{--hud-h:60px;--rail-w:0px;--ctx-w:0px;--dock-h:0px}
  #game,#game.wide{grid-template-columns:1fr;grid-template-rows:var(--hud-h) minmax(0,1fr) 62px}
  #hud{padding:0 10px;gap:10px}
  .hud-player{min-width:0;gap:7px}
  .avatar-hex{width:36px;height:40px}
  .hud-id{display:flex}
  .hud-id strong{font-size:13px;max-width:92px}
  .hud-id span{font-size:9px;margin-top:2px}
  .hud-resources{gap:4px;overflow-x:auto;scrollbar-width:none;mask-image:linear-gradient(90deg,#000 88%,transparent);padding-right:8px}
  .hud-resources::-webkit-scrollbar{display:none}
  .res-chip{min-width:72px;flex:none;height:36px;padding:0 7px 0 5px;gap:5px}
  .res-ico{width:22px;height:22px}
  .res-ico .ico{width:12px;height:12px}
  .res-info b{font-size:12.5px}
  .hud-actions{gap:4px}
  .hud-btn{width:32px;height:32px}
  .hud-btn[data-action="toggle-sound"]{display:none}
  #rail{grid-column:1;grid-row:3;flex-direction:row;padding:0 4px;border-right:0;border-top:1px solid var(--line);gap:0;align-items:stretch;overflow:visible;background:linear-gradient(180deg,rgba(11,18,28,.98),#070c12)}
  .rail-btn{flex:1;height:auto;min-width:0;gap:2px;clip-path:none;padding:7px 1px 5px}
  .rail-btn .ico{width:19px;height:19px}
  .rail-btn span{font-size:8px;letter-spacing:.04em}
  .rail-btn i{left:22%;right:22%;top:0;bottom:auto;width:auto;height:2px;box-shadow:0 0 10px var(--gold)}
  .rail-spacer{display:none}
  .rail-btn[data-view="campaign"],.rail-btn[data-view="alliance"],.rail-more{display:none}
  .rail-more{display:none}
  #main{grid-column:1;grid-row:2}
  .view{padding:8px}
  .panel-view{padding:12px 10px 90px}
  #context{
    position:fixed;left:8px;right:8px;bottom:70px;max-height:56vh;z-index:40;padding:0;overflow-y:auto;
    background:linear-gradient(160deg,rgba(20,31,45,.98),rgba(10,17,26,.99));border:1px solid var(--line-gold);
    clip-path:polygon(0 12px,12px 0,100% 0,100% calc(100% - 12px),calc(100% - 12px) 100%,0 100%);
    box-shadow:0 -20px 60px rgba(0,0,0,.6);transform:translateY(calc(100% + 90px));transition:transform .25s ease;padding:12px;
  }
  #context.open{transform:none}
  #context .ctx-card{border:0;background:none;padding:0;box-shadow:none;clip-path:none}
  #context .ctx-card + .ctx-card{margin-top:12px;border-top:1px solid var(--line);padding-top:12px}
  #context .ctx-card::before{display:none}
  #context .ctx-mobile-close{display:grid}
  #dock{display:none}
  .stage-frame{height:100%}
  .stage-top{padding:10px 12px}
  .stage-title small{font-size:8px}
  .stage-title b{font-size:10.5px}
  .stage-hint{bottom:10px;font-size:8px;letter-spacing:.12em}
  .stage-compass{display:none}
  .world-hud{left:10px;bottom:10px;gap:16px;padding:8px 12px}
  .world-hud b{font-size:15px}
  .world-hud .mini-bar{width:70px}
  .world-legend{display:none}
  .world-controls{right:10px;bottom:10px}
  .view-head{margin-bottom:12px;padding-bottom:10px;flex-wrap:wrap;gap:10px}
  .view-head h1{font-size:22px}
  .view-icon{width:38px;height:38px}
  .view-head p{font-size:10px}
  .view-head .vh-stats{gap:14px}
  .vh-stat b{font-size:16px}
  .army-grid,.tech-grid{grid-template-columns:1fr}
  .hero-layout{grid-template-columns:1fr}
  .hero-portrait{max-height:230px}
  .alliance-layout{grid-template-columns:1fr}
  .mission-card{flex-wrap:wrap;gap:9px}
  .mission-progress{width:100%;order:5}
  .mission-reward{order:6;margin-left:auto}
  .mission-card .btn{width:100%;order:7}
  .train-summary{flex-wrap:wrap;gap:10px}
  .train-summary .progress{width:100%}
  .quick-train{margin-left:0;width:100%}
  .quick-train .btn{flex:1}
  .battle-top{padding:12px 14px;gap:8px}
  .battle-side{width:37vw}
  .battle-side b{font-size:15px}
  .battle-side .bp{font-size:10px}
