function rnd(seed) {
  let s = seed >>> 0;
  return () => {
    s = (s * 1664525 + 1013904223) >>> 0;
    return s / 4294967296;
  };
}

function ridgePath(rng, w, baseY, amp, step, bottom) {
  const pts = [[-20, bottom]];
  let x = -20;
  let y = baseY;
  while (x < w + 40) {
    y = baseY - rng() * amp - Math.sin(x * 0.011) * amp * 0.22;
    pts.push([x, y]);
    x += step * (0.55 + rng() * 0.9);
  }
  pts.push([w + 20, bottom]);
  return pts;
}

