    if(mode==='hideGrid') document.querySelector('.title-grid').style.display='none';
    if(mode==='hideAllAnim') document.querySelectorAll('.title-scan,.title-grid,.title-vignette').forEach(e=>e.style.display='none');
  }, mode);
  await page.waitForTimeout(800);
  const res = await page.evaluate(()=>new Promise(res=>{
