    c.globalAlpha = blink;
    c.fillStyle = '#ffb457';
    c.beginPath();
    c.arc(-4, -50, 1.4, 0, Math.PI * 2);
    c.fill();
    c.restore();
  }

  drawSmoke(seed, t) {
    const c = this.ctx;
    const { h } = this;
    c.save();
    for (let i = 0; i < 17; i++) {
      const p = ((t * 0.000026 + i * 0.058 + seed.ph * 0.03) % 1);
      const r = seed.w * (0.35 + p * 2.6);
      const x = seed.x + Math.sin(p * 5 + seed.ph) * 18 + p * seed.drift * 12;
      const y = seed.y - p * h * 0.42;
      const a = (1 - p) * 0.20 * clamp(p * 9, 0, 1);
      const g = c.createRadialGradient(x, y, 0, x, y, r);
      g.addColorStop(0, `rgba(48,48,46,${a})`);
      g.addColorStop(0.5, `rgba(34,38,40,${a * 0.55})`);
      g.addColorStop(1, 'rgba(20,24,28,0)');
      c.fillStyle = g;
      c.beginPath();
      c.arc(x, y, r, 0, Math.PI * 2);
      c.fill();
    }
    c.restore();
  }

  drawRunway(cx, y, width, t) {
    const c = this.ctx;
    c.save();
    c.globalAlpha = 0.55;
    c.strokeStyle = 'rgba(255,176,82,.16)';
    c.lineWidth = 1;
    for (let i = -1; i <= 1; i += 2) {
      c.beginPath();
      c.moveTo(cx + i * width * 0.22, y);
      c.lineTo(cx + i * width * 0.5, this.h);
      c.stroke();
    }
    for (let i = 0; i < 8; i++) {
      const p = ((t * 0.00007 + i * 0.11) % 1);
      const yy = y + p * (this.h - y);
      c.globalAlpha = (1 - p) * 0.55;
      c.fillStyle = '#ffb45c';
      c.fillRect(cx - 1.5, yy, 3, 7 + p * 20);
    }
    c.restore();
  }

  drawSearchlight(x, y, angle, t) {
    const c = this.ctx;
    const len = this.h * 0.9;
    c.save();
    c.translate(x, y);
    c.rotate(angle);
    const g = c.createLinearGradient(0, 0, 0, -len);
    g.addColorStop(0, 'rgba(210,230,245,.12)');
    g.addColorStop(0.45, 'rgba(160,200,225,.045)');
    g.addColorStop(1, 'rgba(140,190,220,0)');
    c.fillStyle = g;
    c.beginPath();
    c.moveTo(-4, 0);
    c.lineTo(-len * 0.16, -len);
    c.lineTo(len * 0.16, -len);
    c.lineTo(4, 0);
    c.closePath();
    c.fill();
    c.fillStyle = 'rgba(220,240,255,.4)';
    c.beginPath();
    c.arc(0, 0, 2.4, 0, Math.PI * 2);
    c.fill();
    c.restore();
  }

  drawPlane(p, t) {
    const c = this.ctx;
    const { w, h } = this;
    const span = w * 1.45;
    const travel = ((t * 0.001 * p.speed + p.ph * span) % span + span) % span;
    const x = p.d > 0 ? travel - w * 0.25 : w * 1.2 - travel;
    const y = h * p.y + Math.sin(t * 0.0002 + p.ph) * 3;
    c.save();
    c.translate(x, y);
    c.scale(p.s * p.d, p.s);
    const alpha = 0.5;
    c.globalAlpha = alpha;
    c.fillStyle = '#111a22';
    c.beginPath();
    c.moveTo(-18, 0);
    c.lineTo(8, -2.2);
    c.lineTo(18, 0);
    c.lineTo(8, 2.2);
    c.closePath();
    c.fill();
    c.fillRect(-5, -1, 14, 2);
    c.beginPath();
    c.moveTo(-5, 0);
    c.lineTo(-14, -9);
    c.lineTo(-9, -9);
    c.lineTo(1, 0);
    c.closePath();
    c.fill();
    c.beginPath();
    c.moveTo(-5, 0);
    c.lineTo(-14, 9);
    c.lineTo(-9, 9);
    c.lineTo(1, 0);
    c.closePath();
    c.fill();
    // rastro
    const trail = c.createLinearGradient(-80, 0, -12, 0);
    trail.addColorStop(0, 'rgba(180,205,220,0)');
    trail.addColorStop(1, 'rgba(180,205,220,.10)');
    c.fillStyle = trail;
    c.fillRect(-86, -1, 74, 2);
    // luz de navegação
    const blink = Math.sin(t * 0.003 + p.blink) > 0.3 ? 1 : 0.12;
    c.globalAlpha = blink;
    c.fillStyle = '#ff3b2f';
    c.beginPath();
    c.arc(-13, -8, 1.5, 0, Math.PI * 2);
    c.fill();
    c.fillStyle = '#4fe0a0';
    c.beginPath();
    c.arc(-13, 8, 1.5, 0, Math.PI * 2);
    c.fill();
    c.restore();
  }
