import { createRequire } from 'node:module';
import { join } from 'node:path';
import { readFileSync } from 'node:fs';
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'));
const browser = await chromium.launch(config.browser.launchOptions);
for (const [name, viewport, isMobile] of [['mobile',{width:390,height:844},true],['tablet',{width:820,height:1180},true]]) {
  const page = await browser.newPage({ viewport, isMobile, hasTouch: isMobile });
  const errors=[]; page.on('pageerror',e=>errors.push('PAGEERROR '+e.message)); page.on('console',m=>{if(m.type()==='error')errors.push('CONSOLE '+m.text())});
  await page.goto('http://localhost:3002',{waitUntil:'load'});
  await page.waitForSelector('#game.ready',{timeout:15000});
  await page.waitForTimeout(1200);
  const metrics = await page.evaluate(()=>({
    body:[document.body.scrollWidth,document.body.clientWidth],
    game:(()=>{const r=document.querySelector('#game').getBoundingClientRect();return [r.width,r.height]})(),
    rail:[...document.querySelectorAll('#rail .rail-btn')].filter(b=>b.offsetParent).map(b=>b.dataset.view||b.dataset.action)
  }));
  console.log(name,'metrics',JSON.stringify(metrics),'titleHidden',await page.evaluate(()=>document.querySelector('#title-screen').hidden));
  await page.locator('#base-canvas').tap({position:{x:Math.round(viewport.width/2),y:Math.round((viewport.height-140)/2)}});
  await page.waitForTimeout(600);
  const ctxOpen = await page.evaluate(()=>{const e=document.querySelector('#context');const r=e.getBoundingClientRect();return {cls:e.className,x:Math.round(r.x),y:Math.round(r.y),w:Math.round(r.width),h:Math.round(r.height),bottom:Math.round(r.bottom),title:e.querySelector('h2')?.innerText}});
  console.log(name,'ctx',JSON.stringify(ctxOpen));
  await page.screenshot({path:`screenshots/final-${name}-context.png`});
  if (await page.locator('.ctx-mobile-close').count()) { await page.locator('.ctx-mobile-close').tap(); await page.waitForTimeout(400); }
  console.log(name,'closed',await page.evaluate(()=>document.querySelector('#context').className));
  for (const v of ['world','army','research','hero']) {
    await page.locator(`#rail [data-view="${v}"]`).tap(); await page.waitForTimeout(700);
    const m = await page.evaluate(()=>{const e=document.querySelector('#main .view.active');const r=e.getBoundingClientRect();return {rect:[Math.round(r.width),Math.round(r.height)],scroll:[e.scrollWidth,e.scrollHeight],client:[e.clientWidth,e.clientHeight],bodyW:document.body.scrollWidth}});
    console.log(name,v,JSON.stringify(m));
    await page.screenshot({path:`screenshots/final-${name}-${v}.png`});
  }
  // MAIS -> campaign
  await page.locator('#rail .rail-more').tap(); await page.waitForTimeout(500);
  console.log(name,'more modal',await page.locator('#modal-root .modal').count());
  await page.locator('#modal-root [data-view="campaign"]').tap(); await page.waitForTimeout(700);
  console.log(name,'campaign',await page.evaluate(()=>{const e=document.querySelector('#main .view.active');return [e.id,e.scrollWidth,e.clientWidth,document.body.scrollWidth]}));
  await page.screenshot({path:`screenshots/final-${name}-campaign.png`});
  // MAIS -> alliance
  await page.locator('#rail .rail-more').tap(); await page.waitForTimeout(500);
  await page.locator('#modal-root [data-view="alliance"]').tap(); await page.waitForTimeout(700);
  console.log(name,'alliance',await page.evaluate(()=>{const e=document.querySelector('#main .view.active');return [e.id,e.scrollWidth,e.clientWidth,document.body.scrollWidth]}));
  await page.screenshot({path:`screenshots/final-${name}-alliance.png`});
  // world + attack modal
  await page.locator('#rail [data-view="world"]').tap(); await page.waitForTimeout(600);
  await page.locator('.wmarker.enemy').first().tap(); await page.waitForTimeout(600);
  console.log(name,'world selected ctx',await page.evaluate(()=>document.querySelector('#context').className));
  await page.locator('#context [data-action="attack-target"]').tap(); await page.waitForTimeout(500);
  console.log(name,'modal',await page.evaluate(()=>{const m=document.querySelector('#modal-root .modal');if(!m)return null;const r=m.getBoundingClientRect();return {rect:[Math.round(r.x),Math.round(r.y),Math.round(r.width),Math.round(r.height)],scroll:[m.scrollWidth,m.scrollHeight],client:[m.clientWidth,m.clientHeight]}}));
  await page.screenshot({path:`screenshots/final-${name}-modal.png`});
  console.log(name,'errors',errors.length,errors.slice(0,3));
  await page.close();
}
await browser.close();
EOF
